INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('b3f1d305-9a29-43e9-ba1f-023b13ecbe6f'::uuid, 'card_description', 'An Iron Age fort classified as a "slight univallate hillfort." Two sections of banks survive in what is now a nature reserve managed by a wildlife trust.', 'Thought to be the fort the Viking Hastein built in 894, the Danish Camp in Essex has yielded no trace of Viking occupation, but Middle Iron Age pottery and four round houses instead.', 'teaser-card-s030:b3f1d305-9a29-43e9-ba1f-023b13ecbe6f:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'a7b421081c5a65fbc4811d1a774c2a3349fd8b8f15a160e219c00c6775a67872|420cb2fc7b90abb1d9df480d148c79e089ad7e54a848beee3551a613e5fe0f11|420cb2fc7b90abb1d9df480d148c79e089ad7e54a848beee3551a613e5fe0f11', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Thought to be the fort the Viking Hastein built in 894, the Danish Camp in Essex has yielded no trace of Viking occupation, but Middle Iron Age pottery and four round houses instead."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is thought to be the fort that Hastein built [S7]; Hastein is a Viking [S7]; Hastein built the fort in 894 [S7]; the Danish Camp is in Essex [S1]; no trace of Viking occupation has been found at the site [S7]; Middle Iron Age pottery was found [S6]; four round houses were found [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Danish Camp is a fortified settlement [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; Danish Camp is in Essex (at Shoeburyness) [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; The site is thought to be the fort built by the Viking leader Hastein [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; Hastein built a fort at Shoebury in 894 [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; No trace of Viking occupation has been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; Pottery of the Middle Iron Age has been found [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; Four round houses have been found [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]; The site is an Iron Age settlement (Iron Age occupation is what the excavations found instead) [SUPPORTED: https://en.wikipedia.org/wiki/Danish_Camp]"}]'::jsonb),
    ('b44da255-c03d-4304-b7c8-f9e7e8093720'::uuid, 'card_description', 'Dating to 3500–2800 BC on Møn near Klekkende, this passage grave has a chamber and connecting passage. Its kerbstones are among the tallest at any comparable Neolithic monument.', 'On the island of Møn, two entrance passages, almost parallel and facing east, lead into Klekkende Høj. Inside lay human remains, flint weapons, clay vessels and amber jewellery.', 'teaser-card-s030:b44da255-c03d-4304-b7c8-f9e7e8093720:card_description', 'teaser-card-s030 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'f219f7fb3f17e7efdc5c19e84826830b67e4e37944b1c7e53f0d70d1791b9e9e|4f44a1e74094efc24a76d08c04272f38c0a63bed230fb3485e57c7782c72fd90|4f44a1e74094efc24a76d08c04272f38c0a63bed230fb3485e57c7782c72fd90', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the island of Møn, two entrance passages, almost parallel and facing east, lead into Klekkende Høj. Inside lay human remains, flint weapons, clay vessels and amber jewellery."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the tomb is on the island of Møn [S1]; two entrance passages lead into the tomb [S3, S4]; the two passages run almost parallel to each other [S4]; the passages face east [S4]; human remains lay inside [S7]; flint weapons lay inside [S7]; clay vessels lay inside [S7]; amber jewellery lay inside [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Klekkende Høj is a tomb (a megalithic passage grave / burial mound) [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; The tomb lies on the island of Møn [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; The tomb has two entrance passages [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; The two entrance passages run almost parallel to each other [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; The two entrance passages face east [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; Human remains were found inside the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; Flint weapons were found inside the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; Clay vessels were found inside the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]; Amber jewellery was found inside the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Klekkende_H%C3%B8j]"}]'::jsonb),
    ('b50c4816-2378-425f-abae-fa19a9cbaf3c'::uuid, 'card_description', 'A 4th-century BC Scythian kurgan that yielded an elaborate gold pectoral and a gilded gorytos — a combined bow-and-arrow case — despite partial looting before excavation.', 'Robbers looted part of the Scythian Melitopol Kurgan but missed a bronze combat belt in its hiding place. Also found: a gold-coated gorytos with scenes from the myth of Achilles.', 'teaser-card-s030:b50c4816-2378-425f-abae-fa19a9cbaf3c:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'f4f8b3e6ca437be0b4e086281053b5ca920a4b2dd609f46e75c0c87d1cd5a439|ec3be356994a366e8e83e51d4bd43b389607a62f024cd3d8302102f21e232175|ec3be356994a366e8e83e51d4bd43b389607a62f024cd3d8302102f21e232175', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Robbers looted part of the Scythian Melitopol Kurgan but missed a bronze combat belt in its hiding place. Also found: a gold-coated gorytos with scenes from the myth of Achilles."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "robbers looted part of the kurgan [S2, S4]; the kurgan is Scythian [S1]; a bronze combat belt was found [S4]; the robbers missed the belt [S4]; the belt lay in a hiding place [S4]; a gold-coated gorytos was found [S5]; the gorytos shows scenes from the myth of Achilles [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Melitopol Kurgan is a burial mound (kurgan) [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; The kurgan is Scythian [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; The kurgan lies in the city of Melitopol (Ukraine) [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; Robbers looted part of the kurgan [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; The robbers missed a bronze combat belt [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; The bronze combat belt lay in a hiding place [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; A gold-coated gorytos was also found in the kurgan [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]; The gorytos bears scenes from the myth of Achilles [SUPPORTED: https://en.wikipedia.org/wiki/Melitopol_kurgan]"}]'::jsonb),
    ('b5c58acf-f910-4eba-ac18-7c80dc812de2'::uuid, 'card_description', 'A dolmen group with nine large stones forming a polygonal burial chamber and a two-part corridor. A communal funerary site from the 3rd millennium BC.', 'La Chabola de la Hechicera, a dolmen in Elvillar, held human remains and a polished axe of ophite. Its top stone, found broken into three parts, was restored to its assumed place in 1974.', 'teaser-card-s030:b5c58acf-f910-4eba-ac18-7c80dc812de2:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '1c70957768c4cc987824f412698a0fa0cbfc6cd701310673c294712ca8beb0e8|4fd754eb0873fdcac9f16a0753b62a208912e585232e9eabf214f35ec46550e4|4fd754eb0873fdcac9f16a0753b62a208912e585232e9eabf214f35ec46550e4', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Chabola de la Hechicera, a dolmen in Elvillar, held human remains and a polished axe of ophite. Its top stone, found broken into three parts, was restored to its assumed place in 1974."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is a dolmen [S1]; the dolmen is in Elvillar [S1]; human remains were found in it [S4]; a polished axe of ophite was found in it [S4]; the top stone was found broken into three parts [S5]; the top stone was restored to its assumed place [S5]; the restoration was in 1974 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Chabola de la Hechicera is a dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]; The dolmen is in Elvillar [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]; Human remains were found in the dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]; A polished axe was found in the dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]; The polished axe is of ophite [SUPPORTED: https://aunamendi.eusko-ikaskuntza.eus/es/chabola-de-la-hechicera/ar-35637/]; The top stone was found broken into three parts [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]; The top stone was restored and replaced in its assumed original position [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]; The top stone was restored to its place in 1974 [SUPPORTED: https://en.wikipedia.org/wiki/Chabola_de_la_Hechicera]"}]'::jsonb),
    ('b66e9572-4469-4d1a-b13f-b927af5d79db'::uuid, 'card_description', 'Buried by Vesuvius in 472 AD—not the famous 79 AD blast. This later eruption preserved a different era of Roman life under a shallower layer of ash.', 'Unearthed in the 1930s at Somma Vesuviana, a large Roman villa was later interpreted, for its size, as that of the emperor Augustus, where he probably passed his last days of life.', 'teaser-card-s030:b66e9572-4469-4d1a-b13f-b927af5d79db:card_description', 'teaser-card-s030 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '506c7ce79f461d5155c2585e3622e33b73ea9311f4ddf7b3f090afeb1db1b0eb|fdcd24055c240f09de9f695e5b91a8a688ec9c015f6d5464136d75af3db9660b|fdcd24055c240f09de9f695e5b91a8a688ec9c015f6d5464136d75af3db9660b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Unearthed in the 1930s at Somma Vesuviana, a large Roman villa was later interpreted, for its size, as that of the emperor Augustus, where he probably passed his last days of life."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "a Roman villa was unearthed at Somma Vesuviana [S1, S2]; the villa was unearthed in the 1930s [S2]; the villa is large [S2]; the villa was later interpreted as that of the emperor Augustus [S2]; the interpretation was made because of the villa''s size [S2]; Augustus probably passed his last days of life there [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Somma Vesuviana has a Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Somma_Vesuviana]; The Roman villa is large [SUPPORTED: https://en.wikipedia.org/wiki/Somma_Vesuviana]; The villa was unearthed in the 1930s [SUPPORTED: https://en.wikipedia.org/wiki/Somma_Vesuviana]; The villa was later interpreted as that of the emperor Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Somma_Vesuviana]; The interpretation rests on the villa''s size [SUPPORTED: https://en.wikipedia.org/wiki/Somma_Vesuviana]; Augustus probably passed his last days of life there (as the interpretation holds) [SUPPORTED: https://en.wikipedia.org/wiki/Somma_Vesuviana]"}]'::jsonb),
    ('b6ecca26-a3f9-437e-bda5-aa52368598d7'::uuid, 'card_description', 'Yagul is an archaeological site and former city-state associated with the Zapotec civilization of pre-Columbian Mesoamerica.', 'On a volcanic outcrop in the Valley of Oaxaca, the Zapotec city-state of Yagul held more than 6000 people just before the Spanish Conquest. About 30 tombs were found, some in pairs.', 'teaser-card-s030:b6ecca26-a3f9-437e-bda5-aa52368598d7:card_description', 'teaser-card-s030 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '9ab8d723d6bc4630441120bfdad1c3bf5934915225e03ca9ff678dcf8f10a0bc|65363eb696c10a7619f1f04f0778e1fe8d884383527582dc2665265e58ff5fce|65363eb696c10a7619f1f04f0778e1fe8d884383527582dc2665265e58ff5fce', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a volcanic outcrop in the Valley of Oaxaca, the Zapotec city-state of Yagul held more than 6000 people just before the Spanish Conquest. About 30 tombs were found, some in pairs."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Yagul lies on a volcanic outcrop [S5]; Yagul is in the Valley of Oaxaca [S5]; Yagul was a Zapotec city-state [S1]; Yagul had more than 6000 people [S6]; the population figure dates to just before the Spanish Conquest [S6]; about 30 tombs were found [S8]; some of the tombs are in pairs [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Yagul is a city-state [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; Yagul is Zapotec [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; Yagul stands on a volcanic outcrop [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; Yagul lies in the Valley of Oaxaca [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; Yagul held more than 6000 people [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; That population was reached just before the Spanish Conquest [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; About 30 tombs were found at Yagul [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]; Some of the tombs are in pairs [SUPPORTED: https://en.wikipedia.org/wiki/Yagul]"}]'::jsonb),
    ('b7310da2-7ca9-4cb7-b6ec-90b372c8c985'::uuid, 'card_description', 'Bronze Age hypogeum from 1700–1500 BC cut into Mallorcan limestone. Oval and rectangular chambers with benches and niches once held copper daggers, flint knives, and impressed ceramics.', 'On Mallorca lies a set of Bronze Age caves, the Hypogeum of Cala Sant Vicenç. Eight caves are visible today, yet when Wilfrid James Hemp studied them, there were fifteen.', 'teaser-card-s030:b7310da2-7ca9-4cb7-b6ec-90b372c8c985:card_description', 'teaser-card-s030 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '3fca4946d19ccb2705f14887c6a40276503f79bfa4bd29f2c1cea36eaa92c207|442ec330061464ff291ff87844ed3367c15e4b86707aeb3a47c2a0022dba95d6|442ec330061464ff291ff87844ed3367c15e4b86707aeb3a47c2a0022dba95d6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Mallorca lies a set of Bronze Age caves, the Hypogeum of Cala Sant Vicenç. Eight caves are visible today, yet when Wilfrid James Hemp studied them, there were fifteen."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Mallorca [S1]; the site is a set of caves [S1]; the caves date to the Bronze Age [S2]; eight caves are visible today [S3]; Wilfrid James Hemp studied the caves [S3]; there were fifteen caves when Hemp studied them [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Hypogeum of Cala Sant Vicenç is a set of caves (hypogea) (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Cala_Sant_Vicen%C3%A7]; The caves are on the island of Mallorca (Cala Sant Vicenç) [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Cala_Sant_Vicen%C3%A7]; The caves date to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Cala_Sant_Vicen%C3%A7]; Eight caves are visible today [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Cala_Sant_Vicen%C3%A7]; Wilfrid James Hemp studied the caves [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Cala_Sant_Vicen%C3%A7]; There were fifteen caves when Hemp studied them [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Cala_Sant_Vicen%C3%A7]"}]'::jsonb),
    ('b803b66a-768d-4040-bdac-6176611241da'::uuid, 'card_description', 'Type-site of the Horgen culture, 3500–2850 BC, on the south bank of Lake Zurich. Its crude, undecorated pottery links it to the Seine-Oise-Marne culture of northern France.', 'Dredging at Horgen uncovered four levels of occupation parted by lake chalk. The oldest ends in a layer of fire; the next held a house dated by dendrochronology to 3713 BC.', 'teaser-card-s030:b803b66a-768d-4040-bdac-6176611241da:card_description', 'teaser-card-s030 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '278c025e15b62c547d644f758488449303ef6a86eea9b7ce00f371dddcb542cd|d8c603e3b7e3f4af069b635834c77f92a6f4461339a558a49f56deb00f6e69f8|d8c603e3b7e3f4af069b635834c77f92a6f4461339a558a49f56deb00f6e69f8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dredging at Horgen uncovered four levels of occupation parted by lake chalk. The oldest ends in a layer of fire; the next held a house dated by dendrochronology to 3713 BC."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "dredging at Horgen uncovered the remains [S1, S2]; four levels of occupation were identified [S3]; the levels are separated by lake chalk sediments [S3]; the oldest level ends in a fire layer [S4]; the next level held a house [S4]; the house is dated by dendrochronology to 3713 BC [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Horgen has a prehistoric lakeshore occupation site (the coastal station Horgen-Dampfschiffsteg/Bootshabe) with successive levels of occupation (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]; The levels were uncovered by dredging at Horgen [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]; Four levels of occupation were identified [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]; The levels are separated by lake chalk (lacustrine chalk sediments) [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]; The oldest level ends in a layer of fire [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]; The next level held a house [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]; The house is dated by dendrochronology to 3713 BC [SUPPORTED: https://en.wikipedia.org/wiki/Horgen]"}]'::jsonb),
    ('b8b9361e-c77d-4e15-b383-04b7aae6927f'::uuid, 'card_description', 'Gayton Thorpe Roman Villa is the site of a Roman villa, near Gayton Thorpe and about 5 miles east of King''s Lynn, in Norfolk.', 'Found in 1906 near King''s Lynn, Gayton Thorpe Roman Villa gave up two winged corridor buildings. Aerial photographs later showed a detached bathhouse and a ditch enclosing the buildings.', 'teaser-card-s030:b8b9361e-c77d-4e15-b383-04b7aae6927f:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'b8d1617ae095e6014c543aca0f35479b69ea8d77834bfc73302ca5ed4bcc5b6b|0539d53738db473c8e8e2ea602e96613919ea31bd17f03b1dbaf57552a81652e|0539d53738db473c8e8e2ea602e96613919ea31bd17f03b1dbaf57552a81652e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found in 1906 near King''s Lynn, Gayton Thorpe Roman Villa gave up two winged corridor buildings. Aerial photographs later showed a detached bathhouse and a ditch enclosing the buildings."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the villa was found in 1906 [S2]; the villa is near King''s Lynn [S1]; two winged corridor buildings were found [S2]; aerial photographs came later than the first finds [S2, S5]; aerial photographs showed a detached bathhouse [S5]; aerial photographs showed a ditch enclosing the buildings [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Gayton Thorpe Roman Villa is a Roman villa (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Gayton_Thorpe_Roman_Villa]; It lies near King''s Lynn (Norfolk, England) [SUPPORTED: https://en.wikipedia.org/wiki/Gayton_Thorpe_Roman_Villa]; It was found in 1906 [SUPPORTED: https://en.wikipedia.org/wiki/Gayton_Thorpe_Roman_Villa]; Excavation gave up two winged corridor buildings [SUPPORTED: https://en.wikipedia.org/wiki/Gayton_Thorpe_Roman_Villa]; Aerial photographs later showed a detached bathhouse [SUPPORTED: https://en.wikipedia.org/wiki/Gayton_Thorpe_Roman_Villa]; Aerial photographs later showed a ditch enclosing the buildings [SUPPORTED: https://en.wikipedia.org/wiki/Gayton_Thorpe_Roman_Villa]"}]'::jsonb),
    ('b8cd2d69-a83f-4bcc-bad2-999627bb0567'::uuid, 'card_description', 'A 4th-century BC burial mound that yielded a stunning gold wreath, silver vessels, and a complete horse harness with silver fittings. One intact tomb held a chariot and a sacrificed horse.', 'In the center of Vratsa, the Mogilan Mound kept one stone tomb intact. In its chamber lay a gold wreath, earrings and a gilded silver knee pad showing the great mother goddess.', 'teaser-card-s030:b8cd2d69-a83f-4bcc-bad2-999627bb0567:card_description', 'teaser-card-s030 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'e44aa7bdff787d65bbbe2ef6e02618baf20faa9318c98ac51560b4db7941d1c0|0fa8f4ad540c46c0a81bf669eb813f906a11a9fc7d5f5441056ab102b67b5b57|0fa8f4ad540c46c0a81bf669eb813f906a11a9fc7d5f5441056ab102b67b5b57', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the center of Vratsa, the Mogilan Mound kept one stone tomb intact. In its chamber lay a gold wreath, earrings and a gilded silver knee pad showing the great mother goddess."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the mound is in the center of Vratsa [S1]; one stone tomb was found intact [S2, S3]; the tomb has a chamber [S4]; a gold wreath lay in the chamber [S5]; earrings lay in the chamber [S5]; a gilded silver knee pad lay in the chamber [S5]; the knee pad bears an image of the great mother goddess [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Mogilan Mound is a burial mound (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; It lies in the center of Vratsa (Bulgaria) [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; The tombs in the mound are built of stone [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; One tomb was found intact [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; The chamber of the intact tomb held a gold wreath [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; The chamber also held (gold) earrings [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; The chamber also held a gilded silver knee pad [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]; The knee pad shows the great mother goddess [SUPPORTED: https://en.wikipedia.org/wiki/Mogilan_mound]"}]'::jsonb),
    ('b8e5e38c-b300-4fdb-8ef1-ab136542504b'::uuid, 'card_description', 'Two moose carved onto a rock near the river Fossen — one 31 cm, the other 35 cm. Dating to the 6th millennium BC, their position beside the river leaves them submerged during high water levels.', 'Near the river Fossen, the Rock Carvings at Eidefoss show two moose, measuring 31 centimetres and 35 centimetres, on a rock that may have fallen from a nearly vertical cliff.', 'teaser-card-s030:b8e5e38c-b300-4fdb-8ef1-ab136542504b:card_description', 'teaser-card-s030 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '33dd9513609a52daca5fdd9a4560e5acb22ff7436f1441a753e246624bdf4999|ff7820b50e2d847d8eb22ebbc16c0fa557165727c726662d9677f4f57ea31c9a|ff7820b50e2d847d8eb22ebbc16c0fa557165727c726662d9677f4f57ea31c9a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near the river Fossen, the Rock Carvings at Eidefoss show two moose, measuring 31 centimetres and 35 centimetres, on a rock that may have fallen from a nearly vertical cliff."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is near the river Fossen [S1]; the carvings show two moose [S2]; one moose measures 31 centimetres and the other 35 centimetres [S2]; the carvings are on a rock [S3]; the rock may have fallen from a cliff [S3]; the cliff is nearly vertical [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Rock Carvings at Eidefoss are rock carvings (petroglyphs) (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]; They are located near the river Fossen (Nord-Fron, Norway) [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]; The carvings show two moose [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]; One moose measures 31 centimetres [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]; The other moose measures 35 centimetres [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]; The rock on which they are carved may have fallen (uncertain, stated as possible) [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]; The rock may have fallen from a nearly vertical cliff [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_Eidefoss]"}]'::jsonb),
    ('b9024baf-e614-498c-aa14-5c14d2c525b4'::uuid, 'card_description', 'A Numidian city that became a Roman municipality. Excavations uncovered a forum, temple, and baths from what was a bustling North African town.', 'In what was Numidia lie the extensive Roman and Byzantine ruins of Thibilis, whose numerous Latin inscriptions tell of two magistri with annual mandates, assisted by one or two aediles.', 'teaser-card-s030:b9024baf-e614-498c-aa14-5c14d2c525b4:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '1559c503c8a8ca381e012c4709dadd5b356bbddf392aee4587122c13388a6d69|bf9b19b7b7ffc9f5ad733842350114fc0f8ef0c337c03fbf17c6c45d86ba5de7|bf9b19b7b7ffc9f5ad733842350114fc0f8ef0c337c03fbf17c6c45d86ba5de7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In what was Numidia lie the extensive Roman and Byzantine ruins of Thibilis, whose numerous Latin inscriptions tell of two magistri with annual mandates, assisted by one or two aediles."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Thibilis lay in what was Numidia [S1]; the site has extensive Roman and Byzantine ruins [S2]; numerous Latin inscriptions were found at the site [S3]; the inscriptions give evidence about the city''s magistrates [S3]; the city was administered by two magistri with annual mandates [S4]; the magistri were assisted by one or two aediles [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Thibilis is a Roman and Byzantine settlement (a town) [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; The site lies in what was Numidia (today northeast Algeria) [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; The site has extensive ruins [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; The ruins are both Roman and Byzantine [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; Numerous Latin inscriptions were found at Thibilis [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; The inscriptions tell that the city was administered by two magistri [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; The magistri held annual mandates [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]; The two magistri were assisted by one or two aediles [SUPPORTED: https://en.wikipedia.org/wiki/Thibilis]"}]'::jsonb),
    ('ba452543-f3d8-436b-bef5-4329382d234e'::uuid, 'card_description', 'A retaining wall from 19 BC that is all that remains of the Temple Mount''s western side. It has been a site of Jewish prayer for centuries, earning it the name "Wailing Wall."', 'Read the Western Wall from the bottom up: very large Herodian blocks, then medium-sized Umayyad stones, then small, more recent ones. Of its 45 stone courses, 17 lie underground.', 'teaser-card-s030:ba452543-f3d8-436b-bef5-4329382d234e:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '832c7928f07adc8d5f53e5d0d3dd49aae3d6394dfd25bdf2801deb2648129915|208969f636430848b3626fa5105a9cf0e76e8864d867bd1b96539906b0c082e0|208969f636430848b3626fa5105a9cf0e76e8864d867bd1b96539906b0c082e0', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Read the Western Wall from the bottom up: very large Herodian blocks, then medium-sized Umayyad stones, then small, more recent ones. Of its 45 stone courses, 17 lie underground."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the lower courses are very large Herodian blocks [S2]; above them are medium-sized Umayyad stones [S2]; the uppermost courses are small, more recent stones [S2]; the Wall has 45 stone courses [S4]; 17 of the courses lie underground [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Western Wall is an ancient retaining wall of the Temple Mount in Jerusalem [SUPPORTED: https://en.wikipedia.org/wiki/Western_Wall]; The lowest courses are very large Herodian blocks [SUPPORTED: https://en.wikipedia.org/wiki/Western_Wall]; Above the Herodian blocks come medium-sized Umayyad stones [SUPPORTED: https://en.wikipedia.org/wiki/Western_Wall]; The uppermost courses are small stones of more recent date [SUPPORTED: https://en.wikipedia.org/wiki/Western_Wall]; The Wall has 45 stone courses [SUPPORTED: https://en.wikipedia.org/wiki/Western_Wall]; 17 of the 45 courses lie underground [SUPPORTED: https://en.wikipedia.org/wiki/Western_Wall]"}]'::jsonb),
    ('bab70593-9241-44a4-b704-4b0d70c399f9'::uuid, 'card_description', 'Settled since the late Bronze Age around 1200 BC, Miholjanec''s late Iron Age inhabitants were recorded as the bini populi — ''two peoples'' — whose identity remains debated among scholars.', 'On a high plateau at Miholjanec, the bini populi built a hill fort ringed by a moat. Historians are unclear who they were: Scythians, Greeks, Alans and Goths have all been proposed.', 'teaser-card-s030:bab70593-9241-44a4-b704-4b0d70c399f9:card_description', 'teaser-card-s030 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '4bdd04187048650b5ee3828067026ba65d20209313fb99a45c818bfaab34711e|1fbcfdc858d279919347a403d8411f90297878281ff9382948e648306d9f6199|1fbcfdc858d279919347a403d8411f90297878281ff9382948e648306d9f6199', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a high plateau at Miholjanec, the bini populi built a hill fort ringed by a moat. Historians are unclear who they were: Scythians, Greeks, Alans and Goths have all been proposed."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the bini populi built a hill fort [S4]; the fort stood on a high plateau [S4]; the plateau is at Miholjanec [S2, S4]; the fort was surrounded by a moat [S5]; historians are unclear who the bini populi were [S3]; Scythians, Greeks, Alans and Goths have each been proposed as their identity [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Miholjanec (a village in Croatia) stood a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Miholjanec]; The hill fort stood on a high plateau [SUPPORTED: https://en.wikipedia.org/wiki/Miholjanec]; The hill fort was ringed by (surrounded by) a moat [SUPPORTED: https://en.wikipedia.org/wiki/Miholjanec]; The fort was built by the so-called bini populi, who lived in the area in the late Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Miholjanec]; Historians are unclear who the bini populi were [SUPPORTED: https://en.wikipedia.org/wiki/Miholjanec]; Scythians, Greeks, Alans and Goths have all been proposed as their identity [SUPPORTED: https://en.wikipedia.org/wiki/Miholjanec]"}]'::jsonb),
    ('bacd75a6-2248-40b9-bc26-c04b3ecaebe4'::uuid, 'card_description', NULL, 'On a hilltop east of the village of Holbeton in Devon, the Iron Age hill fort of Holbury stands approximately 95 metres above sea level, looking out over the Erme Estuary.', 'teaser-card-s030:bacd75a6-2248-40b9-bc26-c04b3ecaebe4:card_description', 'teaser-card-s030 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '0ab7e9e486a1675ebea4deff624128fee80b3bba451cb428494a187e85ad170c|0d631002bbc13a5ff7f749ecefa3d1db39910c8167d293c5150a0d0a35bf0610|0d631002bbc13a5ff7f749ecefa3d1db39910c8167d293c5150a0d0a35bf0610', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a hilltop east of the village of Holbeton in Devon, the Iron Age hill fort of Holbury stands approximately 95 metres above sea level, looking out over the Erme Estuary."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on a hilltop east of the village of Holbeton [S1, S2]; the site is in Devon [S1]; Holbury is an Iron Age hill fort [S1]; the fort stands approximately 95 metres above sea level [S2]; the fort overlooks the Erme Estuary [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Holbury is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Holbury,_Holbeton]; The hill fort is of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Holbury,_Holbeton]; It lies close to the village of Holbeton in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Holbury,_Holbeton]; The fort is on a hilltop east of the village [SUPPORTED: https://en.wikipedia.org/wiki/Holbury,_Holbeton]; The fort stands approximately 95 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Holbury,_Holbeton]; The fort looks out over the Erme Estuary [SUPPORTED: https://en.wikipedia.org/wiki/Holbury,_Holbeton]"}]'::jsonb),
    ('baece784-4e12-4344-b9e4-bb4ed232ac3e'::uuid, 'card_description', 'The hillfort is sited at the end of the Cefn Meiriadog ridge of the Rhos Hills which offers views over the River Elwy valley in an area dominated by hillforts.', 'Its Welsh name means Giant''s Tomb. Bedd-y-Cawr Hillfort, an Iron Age fort at the end of a ridge, looks over the River Elwy valley, guarded west and east by natural outcrops of limestone.', 'teaser-card-s030:baece784-4e12-4344-b9e4-bb4ed232ac3e:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '195feb07c9ead0fa66fd0498c3f6b191e846808dafa1330d96072ee825243c00|9451a893b7768da3c3c67261d9bf05edfe9aec87e697e3afd03081fccf97adba|9451a893b7768da3c3c67261d9bf05edfe9aec87e697e3afd03081fccf97adba', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its Welsh name means Giant''s Tomb. Bedd-y-Cawr Hillfort, an Iron Age fort at the end of a ridge, looks over the River Elwy valley, guarded west and east by natural outcrops of limestone."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site''s Welsh name means Giant''s Tomb [S2]; the site is called Bedd-y-Cawr Hillfort [S1]; it is an Iron Age fort [S1]; it stands at the end of a ridge [S4]; it looks over the River Elwy valley [S4]; it is protected on the west and east sides by natural outcrops of limestone [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Bedd-y-Cawr Hillfort is a hillfort (in Denbighshire, North Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]; Its Welsh name means Giant''s Tomb [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]; The fort lies at the end of a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]; It looks over the River Elwy valley [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]; It is guarded by natural outcrops of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]; The limestone outcrops guard the west and east sides [SUPPORTED: https://en.wikipedia.org/wiki/Bedd-y-Cawr_Hillfort]"}]'::jsonb),
    ('bb081dcb-3ede-4494-ad64-23bedb36f5b2'::uuid, 'card_description', '1st century AD. Luguvalium was a Roman timber fort south of the Eden River that grew into a full town — possibly the capital of the 4th-century province of Valentia, now beneath Carlisle.', 'Luguvalium, northernmost city of the Roman Empire, grew outside a timber fort Roman armies built around 72 AD south of the River Eden. The fort held around 50 wooden writing tablets.', 'teaser-card-s030:bb081dcb-3ede-4494-ad64-23bedb36f5b2:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'c27d34bf1711c58e4e8e5ec8215c8bd425d6d9a9e2338b134b7bbc46b761fd6d|40d446fd00be5cd21de44735e7f9cc2cc7b404bd02eff367d44ee37e030ee3f4|40d446fd00be5cd21de44735e7f9cc2cc7b404bd02eff367d44ee37e030ee3f4', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Luguvalium, northernmost city of the Roman Empire, grew outside a timber fort Roman armies built around 72 AD south of the River Eden. The fort held around 50 wooden writing tablets."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Luguvalium was the northernmost city of the Roman Empire [S2]; the town of Luguvalium grew up outside a timber fort [S4]; Roman armies built the timber fort around 72 AD [S3]; the fort lay south of the River Eden [S3]; around 50 wooden writing tablets were found within the fort [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Luguvalium was an ancient Roman city in England, within present-day Carlisle, Cumbria [SUPPORTED: https://en.wikipedia.org/wiki/Luguvalium]; Luguvalium was the northernmost city of the Roman Empire [SUPPORTED: https://en.wikipedia.org/wiki/Luguvalium]; Roman armies built a timber fort around 72 AD at a point south of the River Eden [SUPPORTED: https://en.wikipedia.org/wiki/Luguvalium]; The town of Luguvalium grew up outside the timber fort [SUPPORTED: https://en.wikipedia.org/wiki/Luguvalium]; Around 50 wooden writing tablets were found within the fort [SUPPORTED: https://en.wikipedia.org/wiki/Luguvalium]"}]'::jsonb),
    ('bb3b9abe-cc92-4e02-b56f-45531e8d9666'::uuid, 'card_description', 'An Iron Age village continuously occupied for 500 years, with entrance graves, field systems, and standing stones also on site. A rare intact prehistoric landscape.', 'On St Mary''s in the Isles of Scilly, Halangy Down keeps an Iron Age village of attached stone houses on four terraces; digs found bronze brooches, millstones and a slate spindle-whorl.', 'teaser-card-s030:bb3b9abe-cc92-4e02-b56f-45531e8d9666:card_description', 'teaser-card-s030 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '1e3944e5191afbd8305cfb83278cf208e26f2283e9ed0213e53cbe679990e70a|3e43ba02cf34f3656b8135a15b9d741c0434ac79d4e61d0883e77e6063bb1e06|3e43ba02cf34f3656b8135a15b9d741c0434ac79d4e61d0883e77e6063bb1e06', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On St Mary''s in the Isles of Scilly, Halangy Down keeps an Iron Age village of attached stone houses on four terraces; digs found bronze brooches, millstones and a slate spindle-whorl."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Halangy Down is on St Mary''s in the Isles of Scilly [S1]; the site has the remains of an Iron Age village [S2]; the village was made up of attached stone houses [S6]; the settlement complex spans four terraces [S3, S6]; excavations found bronze brooches [S7]; excavations found millstones [S7]; excavations found a slate spindle-whorl [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Halangy Down is a prehistoric settlement on the island of St Mary''s in the Isles of Scilly [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]; The site keeps the remains of an Iron Age village [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]; The village was made up of attached stone houses [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]; The settlement spans four terraces [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]; Excavations found bronze brooches [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]; Excavations found millstones [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]; Excavations found a slate spindle-whorl [SUPPORTED: https://en.wikipedia.org/wiki/Halangy_Down]"}]'::jsonb),
    ('bca65486-49fb-4c72-acff-8df9d0d7f0b3'::uuid, 'card_description', 'A Neolithic passage tomb that began as a henge and was later transformed into a burial mound. A carved pillar inside the chamber and a mysterious "Pattern Stone" remain.', 'Its name means the mound in the dark grove. On Anglesey, Bryn Celli Ddu keeps a complete passage and burial chamber under its mound, and charcoal from two pits there dates to around 4000 BC.', 'teaser-card-s030:bca65486-49fb-4c72-acff-8df9d0d7f0b3:card_description', 'teaser-card-s030 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'a59fa2d7db6d35f2abb4c3552d1abf6444f20a91805ad01f41aa1d3ec28746a8|5ce4fc354b802c2f20a899eecb214f0d91b3f2df51c94b4e3e36c07f2126ab0e|5ce4fc354b802c2f20a899eecb214f0d91b3f2df51c94b4e3e36c07f2126ab0e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its name means the mound in the dark grove. On Anglesey, Bryn Celli Ddu keeps a complete passage and burial chamber under its mound, and charcoal from two pits there dates to around 4000 BC."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the name Bryn Celli Ddu means the mound in the dark grove [S2]; the site is on Anglesey [S1]; its passage and burial chamber are complete [S5]; the passage and chamber lie under a mound [S5]; charcoal from two pits at the site dates to around 4000 BC [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Bryn Celli Ddu is a prehistoric site (a passage tomb) on the Welsh island of Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Celli_Ddu]; Bryn Celli Ddu is a passage tomb [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Celli_Ddu]; The name Bryn Celli Ddu means the mound in the dark grove [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Celli_Ddu]; The site keeps a complete passage and burial chamber under its mound [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Celli_Ddu]; Charcoal from two pits at the site dates to around 4000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Bryn_Celli_Ddu]"}]'::jsonb),
    ('bcc037db-7637-44c9-8204-3ce6d4370653'::uuid, 'card_description', 'An Aboriginal greenstone quarry known as Wil-im-ee moor-ring — ''axe place.'' Axes from this quarry were traded across hundreds of kilometers through established exchange networks.', 'Its Woiwurrung name means axe place. At the Mount William Stone Axe Quarry, Aboriginal people dug greenstone from 268 mining pits and roughly flaked it into blanks for axe heads.', 'teaser-card-s030:bcc037db-7637-44c9-8204-3ce6d4370653:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '9b90f23511acc06e4ec73db87571e0b5479296a2ab31b57cf01320fc79536636|76a819cdbc8d29cc04778d85c3d1c2c2d722ac7be5e2030004eb12e47827218d|76a819cdbc8d29cc04778d85c3d1c2c2d722ac7be5e2030004eb12e47827218d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its Woiwurrung name means axe place. At the Mount William Stone Axe Quarry, Aboriginal people dug greenstone from 268 mining pits and roughly flaked it into blanks for axe heads."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site''s Woiwurrung name means axe place [S2]; Aboriginal people dug greenstone at the quarry [S3, S4]; there are 268 mining pits [S5]; the greenstone was roughly flaked into blanks [S4]; the blanks were for axe heads [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Mount William Stone Axe Quarry is an Aboriginal Australian archaeological site (a greenstone axe quarry) in Victoria, Australia [SUPPORTED: https://en.wikipedia.org/wiki/Mount_William_stone_axe_quarry]; Its Woiwurrung name means axe place [SUPPORTED: https://en.wikipedia.org/wiki/Mount_William_stone_axe_quarry]; Aboriginal people dug greenstone at the quarry [SUPPORTED: https://en.wikipedia.org/wiki/Mount_William_stone_axe_quarry]; The quarry has 268 mining pits [SUPPORTED: https://en.wikipedia.org/wiki/Mount_William_stone_axe_quarry]; The greenstone was roughly flaked into blanks for axe heads [SUPPORTED: https://en.wikipedia.org/wiki/Mount_William_stone_axe_quarry]"}]'::jsonb),
    ('bd4a0096-d99c-4a9d-92e1-a2592c69fe99'::uuid, 'card_description', 'Perched 1,500 metres above sea level beside the Vilesh River, this Middle Palaeolithic cave was occupied around 50,000 BC — among the highest-altitude Palaeolithic sites in the Caucasus.', 'High on the left bank of the Vilesh River, 1,500 metres above sea level, Allar Cave sheltered Middle Paleolithic people. Found in 1993, it gave up nine stone items of their age.', 'teaser-card-s030:bd4a0096-d99c-4a9d-92e1-a2592c69fe99:card_description', 'teaser-card-s030 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '9e38e9b704398c0d3902f4c2a268f5560680d5ebaa272a64da4d20a88b3fa2e8|0e45abe6f0f544b70e9444982d909a1ef0d9b0c2a63a2d2bef57d22f691c099a|0e45abe6f0f544b70e9444982d909a1ef0d9b0c2a63a2d2bef57d22f691c099a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "High on the left bank of the Vilesh River, 1,500 metres above sea level, Allar Cave sheltered Middle Paleolithic people. Found in 1993, it gave up nine stone items of their age."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the cave is on the left bank of the Vilesh River [S2]; the cave lies at 1,500 metres above sea level [S2]; the cave was a Middle Paleolithic human settlement, sheltering Middle Paleolithic people [S1]; the cave was found in 1993 [S3]; nine Middle Paleolithic stone items were uncovered [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Allar Cave is an archaeological site, a cave settlement of Middle Paleolithic people, in Azerbaijan [SUPPORTED: https://en.wikipedia.org/wiki/Allar_Cave]; The cave lies on the left bank of the Vilesh River [SUPPORTED: https://en.wikipedia.org/wiki/Allar_Cave]; The cave is 1,500 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Allar_Cave]; Allar Cave sheltered Middle Paleolithic people [SUPPORTED: https://en.wikipedia.org/wiki/Allar_Cave]; The cave was found in 1993 [SUPPORTED: https://en.wikipedia.org/wiki/Allar_Cave]; The expedition found nine Middle Paleolithic stone items [SUPPORTED: https://en.wikipedia.org/wiki/Allar_Cave]"}]'::jsonb),
    ('bdf88679-e9b7-4344-a3ed-212184e26102'::uuid, 'card_description', 'Authentic archaeological finds from the Neolithic period have been discovered on Palagruža, including a small number of early Neolithic Impressed Ware pottery dated to the 6th–4th millennia BC.', 'In the middle of the Adriatic Sea, Palagruža has given up early Neolithic Impressed Ware pottery of the 6th–4th millennia BC and substantial finds from ancient Greek seafarers.', 'teaser-card-s030:bdf88679-e9b7-4344-a3ed-212184e26102:card_description', 'teaser-card-s030 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '90e64f64c098f0067d3941c533d879b18269330f10b7613b9e15764d4c5ec790|bc9a1e432b3a68ecf771417c8c0db241e053edf120c759612ee9a2b8e65d0e65|bc9a1e432b3a68ecf771417c8c0db241e053edf120c759612ee9a2b8e65d0e65', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the middle of the Adriatic Sea, Palagruža has given up early Neolithic Impressed Ware pottery of the 6th–4th millennia BC and substantial finds from ancient Greek seafarers."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Palagruža lies in the middle of the Adriatic Sea [S1]; early Neolithic Impressed Ware pottery has been found there [S2]; the pottery dates to the 6th-4th millennia BC [S2]; there are substantial finds from ancient Greek seafarers [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Palagruža is an island group (archipelago, an archaeological site) [SUPPORTED: https://en.wikipedia.org/wiki/Palagru%C5%BEa]; Palagruža lies in the middle of the Adriatic Sea [SUPPORTED: https://en.wikipedia.org/wiki/Palagru%C5%BEa]; Palagruža has yielded early Neolithic Impressed Ware pottery [SUPPORTED: https://en.wikipedia.org/wiki/Palagru%C5%BEa]; The Impressed Ware pottery dates to the 6th-4th millennia BC [SUPPORTED: https://en.wikipedia.org/wiki/Palagru%C5%BEa]; Palagruža has substantial finds from ancient Greek seafarers [SUPPORTED: https://en.wikipedia.org/wiki/Palagru%C5%BEa]"}]'::jsonb),
    ('bebb7616-5341-4fd5-a69e-ee430e59c44f'::uuid, 'card_description', 'A hilltop with a summit cairn whose surrounding peat has been dated to around 1500 BC. The uniformly aged peat suggests the cairn was built when the hilltop was freshly cleared.', 'On the Howden Moors, peat near the summit cairn of Margery Hill is uniformly about 3,500 years old, a sign it was built, not natural: believed part of a Bronze Age burial mound.', 'teaser-card-s030:bebb7616-5341-4fd5-a69e-ee430e59c44f:card_description', 'teaser-card-s030 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'e7690931cdafef635ace29e58743650fc43c99392c9ba6dacda76cda5c9dc2ca|e33cb2260243ef0f9f21b5c0d71016e58c820ebfcb16181f6d3c02b32d000b25|e33cb2260243ef0f9f21b5c0d71016e58c820ebfcb16181f6d3c02b32d000b25', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Howden Moors, peat near the summit cairn of Margery Hill is uniformly about 3,500 years old, a sign it was built, not natural: believed part of a Bronze Age burial mound."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Margery Hill is on the Howden Moors [S1]; peat near the summit cairn is uniformly about 3,500 years old [S4]; the uniform age indicates the cairn was built rather than natural [S4]; it is believed to have been part of a Bronze Age burial mound [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Margery Hill is a hill on the Howden Moors with a summit cairn (a burial-mound site) [SUPPORTED: https://en.wikipedia.org/wiki/Margery_Hill]; Peat near the summit cairn is uniformly about 3,500 years old [SUPPORTED: https://en.wikipedia.org/wiki/Margery_Hill]; The uniform peat age indicates the cairn was built, not natural [SUPPORTED: https://en.wikipedia.org/wiki/Margery_Hill]; The cairn is believed to be part of a Bronze Age burial mound [SUPPORTED: https://en.wikipedia.org/wiki/Margery_Hill]"}]'::jsonb),
    ('befdcbb6-1a51-45eb-9ed3-30281f402bcf'::uuid, 'card_description', 'A Bronze Age hill fort with a single circular rampart 250 metres in diameter. Three holloway entrances are flanked by linear banks extending from the perimeter.', 'Near Taunton, a single rampart up to 3 m high rings Norton Camp, a Bronze Age hill fort about 250 m across, where digs found hoards of bronze metalwork, 9 bracelets and sword moulds.', 'teaser-card-s030:befdcbb6-1a51-45eb-9ed3-30281f402bcf:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '3397e9f1a6a98ff33212638ddad43f434f936d255f3079de211d3d3332532a7e|d449d7dd8ca46269e735c1b44af3b2235c98de5947bdeba84b25593d55542fce|d449d7dd8ca46269e735c1b44af3b2235c98de5947bdeba84b25593d55542fce', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Taunton, a single rampart up to 3 m high rings Norton Camp, a Bronze Age hill fort about 250 m across, where digs found hoards of bronze metalwork, 9 bracelets and sword moulds."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Norton Camp is near Taunton [S1]; a single rampart up to 3 m high encircles the site [S2]; it is a Bronze Age hill fort [S1]; the ring is about 250 m across [S3]; excavations found hoards of bronze metalwork [S5]; excavations found 9 bracelets [S5]; excavations found sword moulds [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Norton Camp is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; Norton Camp is of the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; Norton Camp is near Taunton [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; A single rampart rings the fort [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; The rampart is up to 3 m high [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; The fort is about 250 m across [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; Excavations found hoards of bronze metalwork [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; Excavations found 9 bracelets [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]; Excavations found sword moulds [SUPPORTED: https://en.wikipedia.org/wiki/Norton_Camp]"}]'::jsonb),
    ('bf24be84-f6ea-4f68-9b22-2274d0a4c6e5'::uuid, 'card_description', 'The town was in use Early Minoan II to Late Minoan IIIA, and the nearby peak sanctuary was in use until at least Late Minoan IA.', 'Houses, a cistern and an aqueduct with clay pipes remain at Tylissos, a Minoan town where digs found a pithos inscribed in Linear A, stone horns and clay figurines of humans and animals.', 'teaser-card-s030:bf24be84-f6ea-4f68-9b22-2274d0a4c6e5:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '3c74992799f0d9574236a19ea0bc6bcd78db10d99b515e2ad6c8ce33f20b6590|3c04865c4186634847e84bd391b55bea9da619b57bb11d203c21ef421fcf0719|3c04865c4186634847e84bd391b55bea9da619b57bb11d203c21ef421fcf0719', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Houses, a cistern and an aqueduct with clay pipes remain at Tylissos, a Minoan town where digs found a pithos inscribed in Linear A, stone horns and clay figurines of humans and animals."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the structures at Tylissos include houses [S3]; the structures include a cistern [S3]; the structures include an aqueduct with clay pipes [S3]; Tylissos was a Minoan town [S2]; excavations found a pithos with Linear A inscriptions [S4]; excavations found stone horns [S4]; excavations found clay figurines of humans and animals [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tylissos is a Minoan town (ancient city of the Minoan era, near Tylisos on Crete) [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]; Houses remain at Tylissos [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]; A cistern remains at Tylissos [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]; An aqueduct with clay pipes remains at Tylissos [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]; Digs found a pithos inscribed in Linear A [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]; Digs found stone horns [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]; Digs found clay figurines of humans and animals [SUPPORTED: https://en.wikipedia.org/wiki/Tylissos]"}]'::jsonb),
    ('bf53f267-7a43-4af9-a8d3-1e270d40b85e'::uuid, 'card_description', 'A Neolithic burial cairn with a rare double-tiered chamber—upper and lower, originally separate. Why they stacked the chambers remains unknown.', 'On Rousay, the Neolithic Taversöe Tuick Chambered Cairn holds a rare double-tiered chamber, an upper one over a subterranean one, and a small channel leading to a third miniature chamber.', 'teaser-card-s030:bf53f267-7a43-4af9-a8d3-1e270d40b85e:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '30e2f43ce65c71946a67e699b499a64f91cecf264384bf8715c477ae8b26d007|8db1acfe201b497755fc2f570719fbf468031fa28493301815077e4f0336972b|8db1acfe201b497755fc2f570719fbf468031fa28493301815077e4f0336972b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Rousay, the Neolithic Taversöe Tuick Chambered Cairn holds a rare double-tiered chamber, an upper one over a subterranean one, and a small channel leading to a third miniature chamber."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Rousay [S1]; the cairn is Neolithic [S1]; it has a rare double-tiered chamber [S2]; the tiers are an upper chamber and a subterranean lower chamber [S2]; a small channel links the lower chamber to a third miniature chamber [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Taversöe Tuick is a chambered (burial) cairn on Rousay [SUPPORTED: https://en.wikipedia.org/wiki/Taversoe_Tuick]; Taversöe Tuick is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Taversoe_Tuick]; It holds a rare double-tiered chamber [SUPPORTED: https://en.wikipedia.org/wiki/Taversoe_Tuick]; The double-tiered chamber is an upper chamber over a subterranean (lower) one [SUPPORTED: https://en.wikipedia.org/wiki/Taversoe_Tuick]; A small channel leads from the lower chamber [SUPPORTED: https://en.wikipedia.org/wiki/Taversoe_Tuick]; The channel leads to a third miniature chamber [SUPPORTED: https://en.wikipedia.org/wiki/Taversoe_Tuick]"}]'::jsonb),
    ('bf730d05-edd1-42cf-8746-a081c4ac78a6'::uuid, 'card_description', 'At 1,200 metres above sea level, Barriles yielded stone sculptures of warriors standing atop captives — signs of ranked society and conquest culture by 300 AD.', 'In the highlands of Chiriquí, 1,200 meters up, a small mound at Barriles once had a row of 14 statues. In four, a figure, often in a conical hat, rides on the shoulders of a naked man.', 'teaser-card-s030:bf730d05-edd1-42cf-8746-a081c4ac78a6:card_description', 'teaser-card-s030 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '3d0a52c1a89a08ffb26b210273ab35377effb48b85c5432554acd536bb30fbb7|a49f77e5d6024ced9b48103e808783a8cea144457a6655d6b8b2b6aa8558d59a|a49f77e5d6024ced9b48103e808783a8cea144457a6655d6b8b2b6aa8558d59a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the highlands of Chiriquí, 1,200 meters up, a small mound at Barriles once had a row of 14 statues. In four, a figure, often in a conical hat, rides on the shoulders of a naked man."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Barriles is in the highlands of Chiriqui [S2]; it lies at 1,200 meters above sea level [S2]; a small mound at the site was once associated with a row of 14 statues [S4]; four of the statues show a figure riding on the shoulders of a naked man [S5]; the riding figure is often in a conical hat [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Barriles is an archaeological site (a socioceremonial center with a residential population) in the highlands of Chiriquí, Panama [SUPPORTED: https://en.wikipedia.org/wiki/Barriles]; The site lies 1,200 meters above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Barriles]; A small mound at Barriles was once associated with a row of 14 statues [SUPPORTED: https://en.wikipedia.org/wiki/Barriles]; Four of the statues show a figure riding on the shoulders of a naked man [SUPPORTED: https://en.wikipedia.org/wiki/Barriles]; The figure riding on the shoulders of a naked man is often in a conical hat [SUPPORTED: https://en.wikipedia.org/wiki/Barriles]"}]'::jsonb),
    ('bfcc8547-38c2-4af1-bb54-79a47c79daea'::uuid, 'card_description', 'A Roman palace basilica containing the largest surviving hall from antiquity -- 67 metres long, 33 metres high. The floor was once black-and-white marble with heated walls.', 'In Trier, the Basilica of Constantine holds the largest extant hall from classical antiquity, 33 m high, built of solid brick between AD 300 and 310 with black-and-white marble floors.', 'teaser-card-s030:bfcc8547-38c2-4af1-bb54-79a47c79daea:card_description', 'teaser-card-s030 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '317289cecddd66fb2fc184881419e999342c204607dfd741180ed245864eb871|4de783373d8870f538b7941b67b01f148acfc04b0e5578c6969ff19664b3b0b9|4de783373d8870f538b7941b67b01f148acfc04b0e5578c6969ff19664b3b0b9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Trier, the Basilica of Constantine holds the largest extant hall from classical antiquity, 33 m high, built of solid brick between AD 300 and 310 with black-and-white marble floors."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the basilica is in Trier [S1]; it contains the largest extant hall from classical antiquity [S2]; the hall is 33 m high [S3]; it was built of solid brick [S6]; it was built between AD 300 and 310 [S1]; it has black-and-white marble floors [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Basilica of Constantine is a Roman palace basilica at Trier, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Aula_Palatina]; The basilica contains the largest extant hall from classical antiquity [SUPPORTED: https://en.wikipedia.org/wiki/Aula_Palatina]; The hall is 33 m high [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Aula_Palatina]; It was built of solid brick [SUPPORTED: https://en.wikipedia.org/wiki/Aula_Palatina]; It was built between AD 300 and 310 [SUPPORTED: https://en.wikipedia.org/wiki/Aula_Palatina]; It has black-and-white marble floors [SUPPORTED: https://en.wikipedia.org/wiki/Aula_Palatina]"}]'::jsonb),
    ('bfe38998-f394-4d5e-9a90-1fe222f8f106'::uuid, 'card_description', 'A Proto-Norse runestone from 200-450 AD, inscribed in Elder Futhark runes. It may be the oldest written record of burial rites and inheritance in its region.', 'Found in 1627 in a churchyard wall, the Tune Stone carries Proto-Norse runes from circa 200–450 AD, possibly the oldest Norwegian attestation of burial rites, inheritance and beer.', 'teaser-card-s030:bfe38998-f394-4d5e-9a90-1fe222f8f106:card_description', 'teaser-card-s030 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'a676057d6fc0f87978d79186e057fad92c8ea0b36cc0525041d23f43c16bc9f0|476201755d9faa25a5e6894e8bbef5c7a313ddae7229dade8d7531c35c6cd7af|476201755d9faa25a5e6894e8bbef5c7a313ddae7229dade8d7531c35c6cd7af', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found in 1627 in a churchyard wall, the Tune Stone carries Proto-Norse runes from circa 200–450 AD, possibly the oldest Norwegian attestation of burial rites, inheritance and beer."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the stone was found in 1627 [S3]; it was found in a churchyard wall [S3]; it carries runes in the Proto-Norse language [S1, S2]; the inscription dates to circa 200-450 AD [S1]; it is possibly the oldest Norwegian attestation of burial rites, inheritance and beer [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Tune Stone is a runestone (from Tune, Østfold, Norway) [SUPPORTED: https://en.wikipedia.org/wiki/Tune_stone]; The stone was found in 1627 in a churchyard wall [SUPPORTED: https://en.wikipedia.org/wiki/Tune_stone]; Its runes are Proto-Norse [SUPPORTED: https://en.wikipedia.org/wiki/Tune_stone]; The runes date from circa 200–450 AD [SUPPORTED: https://en.wikipedia.org/wiki/Tune_stone]; It is possibly the oldest Norwegian attestation of burial rites, inheritance and beer [SUPPORTED: https://en.wikipedia.org/wiki/Tune_stone]"}]'::jsonb),
    ('c010f54a-5ced-4bf6-973b-89fd6130cf14'::uuid, 'card_description', 'A city with settlement traces from the 6th millennium BC, home to Neolithic Lengyel and Globular Amphora cultures. It later became an outpost of the Roman Empire.', 'Its oldest preserved name is Hammeum. Prokuplje lay on the Roman Via Militaris, the road linking the central Balkans with the Adriatic, and in July 2008 a major Roman spa came to light.', 'teaser-card-s030:c010f54a-5ced-4bf6-973b-89fd6130cf14:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '7d0b61a5dc835e0d4ff4468b0dbb3c172c2362db15ecc4a916e025e8fba1c334|61fb386c02ba470b88b87c4bec213ccd070b0626fafbc64a07bfcf29ef8b3865|61fb386c02ba470b88b87c4bec213ccd070b0626fafbc64a07bfcf29ef8b3865', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its oldest preserved name is Hammeum. Prokuplje lay on the Roman Via Militaris, the road linking the central Balkans with the Adriatic, and in July 2008 a major Roman spa came to light."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the settlement''s oldest preserved name is Hammeum [S3]; the settlement lay on the Roman Via Militaris [S4]; the Via Militaris connected the central Balkans with the Adriatic [S4]; a major Roman spa was unearthed in July 2008 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Prokuplje is a city (a settlement of Roman times) in southern Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Prokuplje]; The settlement''s oldest preserved name is Hammeum [SUPPORTED: https://en.wikipedia.org/wiki/Prokuplje]; Prokuplje (Roman Hammeum) lay on the Roman Via Militaris [SUPPORTED: https://en.wikipedia.org/wiki/Prokuplje]; The Via Militaris was the road linking the central Balkans with the Adriatic [SUPPORTED: https://en.wikipedia.org/wiki/Prokuplje]; A major Roman spa came to light in July 2008 [SUPPORTED: https://en.wikipedia.org/wiki/Prokuplje]"}]'::jsonb),
    ('c015ceea-eeb0-4296-9913-390eb795727b'::uuid, 'card_description', 'Rigorous excavation and research occurred at Cerro Sechin after its 1937 discovery by Tello and Xesspe.', 'In the Casma Province, the approximately 300 bas-reliefs of Cerro Sechín show axe-wielding warriors, body parts and victims, carved figures that graphically dramatize human sacrifices.', 'teaser-card-s030:c015ceea-eeb0-4296-9913-390eb795727b:card_description', 'teaser-card-s030 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '1656614e3d07ee718e29bbeea44cc5bb4e9a37789222352acb5902c45b9b7f73|22cd05e39212688c59eaeec15865c54ba69fa8674f52874c78e4e33c2fbdfb94|22cd05e39212688c59eaeec15865c54ba69fa8674f52874c78e4e33c2fbdfb94', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Casma Province, the approximately 300 bas-reliefs of Cerro Sechín show axe-wielding warriors, body parts and victims, carved figures that graphically dramatize human sacrifices."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in the Casma Province [S1]; approximately 300 bas-reliefs [S8]; showing axe-wielding warriors, body parts and victims [S8]; carved figures graphically dramatize human sacrifices [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cerro Sechín is an archaeological site in the Casma Province, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_Sech%C3%ADn]; There are approximately 300 bas-reliefs [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_Sech%C3%ADn]; They show axe-wielding warriors [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_Sech%C3%ADn]; They show body parts and victims [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_Sech%C3%ADn]; The carved figures graphically dramatize human sacrifices [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_Sech%C3%ADn]"}]'::jsonb),
    ('c04dfddb-2904-41a4-9351-18f4e6f79907'::uuid, 'card_description', 'Bronze Age enclosure of 0.5 hectares near Cerne Abbas, occupied 2500–800 BC. A Martin Down style domestic settlement on chalk downland — one of many such farmsteads once found across the Dorset hills.', 'Banks up to 1.2 metres high and sunken trackways up to 1.7 metres deep mark the Shearplace Hill Enclosure in Dorset, a Bronze Age farmstead whose main enclosure held two round houses.', 'teaser-card-s030:c04dfddb-2904-41a4-9351-18f4e6f79907:card_description', 'teaser-card-s030 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'd821a8fca096aaa6ec212b4c04e786c490d498c3513afe619563b051db1c2583|9179c74c57470691328b919fa1717032b93f67e7eb05c99ec63a02e3bd232d4e|9179c74c57470691328b919fa1717032b93f67e7eb05c99ec63a02e3bd232d4e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Banks up to 1.2 metres high and sunken trackways up to 1.7 metres deep mark the Shearplace Hill Enclosure in Dorset, a Bronze Age farmstead whose main enclosure held two round houses."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "banks up to 1.2 metres high mark the site [S3]; sunken trackways up to 1.7 metres deep mark the site [S3]; the site is in Dorset [S1]; the site is Bronze Age [S1, S5]; it was a farmstead [S5]; the main (principal) enclosure held two round houses [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Shearplace Hill Enclosure is a Bronze Age archaeological site (an enclosure) [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; The site is in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; It was a farmstead [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; The farmstead was occupied in the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; Banks at the site reach up to 1.2 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; Sunken trackways at the site reach up to 1.7 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; The farmstead had a main (principal) enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]; The main enclosure held two round houses [SUPPORTED: https://en.wikipedia.org/wiki/Shearplace_Hill_Enclosure]"}]'::jsonb),
    ('c06cb387-e065-4bcd-bbbe-a6b9d1a4082d'::uuid, 'card_description', 'From Seaton in Devon to Dover in Kent, with finds dated to 600–450 BC and use stretching back to the Stone Age. Its eastern segment was rebranded the Pilgrims'' Way in the 19th century.', 'From Seaton to Dover ran the Harrow Way, an ancient trackway dated to 600 to 450 BC but probably in existence since the Stone Age. Its eastern part was later known as the Pilgrims'' Way.', 'teaser-card-s030:c06cb387-e065-4bcd-bbbe-a6b9d1a4082d:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'b0e312c059f6f334f05a8736cc9b8c87502024e10358f3147a4ff4de3a06a5c5|c4193b0a38249a512c42e4071a77c33cb64435bc540fbd140940846932b80bc0|c4193b0a38249a512c42e4071a77c33cb64435bc540fbd140940846932b80bc0', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "From Seaton to Dover ran the Harrow Way, an ancient trackway dated to 600 to 450 BC but probably in existence since the Stone Age. Its eastern part was later known as the Pilgrims'' Way."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Harrow Way ran from Seaton to Dover [S1, S2]; it is an ancient trackway [S1]; it is dated to 600 to 450 BC [S1]; it probably existed since the Stone Age [S1]; its eastern part was later known as the Pilgrims'' Way [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Harrow Way is an ancient trackway in the south of England [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Way]; It ran from Seaton to Dover [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Way]; It is dated to 600 to 450 BC [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Way]; It is probably in existence since the Stone Age [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Way]; Its eastern part was later known as the Pilgrims'' Way [SUPPORTED: https://en.wikipedia.org/wiki/Harrow_Way]"}]'::jsonb),
    ('c097eec0-60d9-4c1c-84f7-16e869dd5ccd'::uuid, 'card_description', 'A circle of 55 close-set slate stones, 26.8 m across, with a southeast entrance gap. The Lake District saw more stone circles built than almost anywhere.', 'Beside Swinside Fell in southern Cumbria, the stone circle of Swinside, also called Sunkenkirk, opens to the south-east between two large portal stones set outside its ring of slate.', 'teaser-card-s030:c097eec0-60d9-4c1c-84f7-16e869dd5ccd:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'b8d33461ac82d07338918a8ff11174f196f5cf0a22dacbcc33de4eabdbed7c0d|fb4da552fc5b4138f0f989fa014709373d7ec29f256b2323499a6a30a23175c1|fb4da552fc5b4138f0f989fa014709373d7ec29f256b2323499a6a30a23175c1', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beside Swinside Fell in southern Cumbria, the stone circle of Swinside, also called Sunkenkirk, opens to the south-east between two large portal stones set outside its ring of slate."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies beside Swinside Fell [S1]; the site is in southern Cumbria [S1]; Swinside is a stone circle [S1]; it is also called Sunkenkirk [S1]; its entrance opens to the south-east [S4]; the entrance lies between two large portal stones [S4]; the portal stones are set outside the circle''s circumference [S4]; the ring is made of slate [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Swinside is a stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; The stone circle lies beside Swinside Fell [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; It lies in southern Cumbria [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; Swinside is also called Sunkenkirk [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; The ring is built of slate [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; The circle opens (has its entrance) to the south-east [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; The entrance lies between two portal stones [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; The two portal stones are large [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]; The portal stones are set outside the ring [SUPPORTED: https://en.wikipedia.org/wiki/Swinside]"}]'::jsonb),
    ('c1fce6e2-c6ef-4f9b-89c5-41809188c6ea'::uuid, 'card_description', 'A 1st-century AD broch on Tiree with walls 4.5 metres thick — nearly half the building''s total diameter. Occupation debris spans centuries of continuous use.', 'On Tiree''s north coast, Dun Mor Vaul is a drystone tower with walls about 4.5 metres thick. Before it, in the 5th century BC, a wooden hut seems to have stood here, perhaps lost to fire.', 'teaser-card-s030:c1fce6e2-c6ef-4f9b-89c5-41809188c6ea:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'd4ca8f6a363942fc639fc28f7480a29229fe66ca22eb5f94e8c606d44740453d|b4e4f04548d44a246dfed9b90cef8ec5ce4bb77c4732f985e612eb0504d67aa1|b4e4f04548d44a246dfed9b90cef8ec5ce4bb77c4732f985e612eb0504d67aa1', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Tiree''s north coast, Dun Mor Vaul is a drystone tower with walls about 4.5 metres thick. Before it, in the 5th century BC, a wooden hut seems to have stood here, perhaps lost to fire."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Tiree''s north coast [S1]; the broch is a drystone tower [S2]; its walls are about 4.5 metres thick [S2]; a phase of occupation came before the broch was built [S4, S5]; in the 5th century BC a wooden hut appears to have stood there (hedged) [S5]; the hut may have been destroyed by fire (hedged) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dun Mor Vaul is a drystone tower (a broch) [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]; It lies on Tiree''s north coast [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]; Its walls are about 4.5 metres thick [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]; Before the tower there was an earlier phase of occupation on the site [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]; The earlier phase dates to the 5th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]; A wooden hut seems to have stood on the site [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]; The hut was perhaps lost to fire [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Mor_Vaul]"}]'::jsonb),
    ('c2c96c29-4454-401b-ac54-21d2ba77fdbb'::uuid, 'card_description', 'A Samnite town in the Vulturnus valley that came under Roman control after fierce resistance. Pliny and Silius Italicus both recorded its name, placing it near the Campanian border.', 'Below the Monte Matese, the walls of Roman Allifae enclose the remains of large baths and a theatre. Where the Samnite city stood, with its own coinage in the 4th century BC, is not known.', 'teaser-card-s030:c2c96c29-4454-401b-ac54-21d2ba77fdbb:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '11c43ba71120817301db05c8e2b1dac36e427894127ee0f8fd7baca31e4d4702|c162fdb22bcc49119ebcfa328a3780f6e91a195eb0693b900e3374847786b860|c162fdb22bcc49119ebcfa328a3780f6e91a195eb0693b900e3374847786b860', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Below the Monte Matese, the walls of Roman Allifae enclose the remains of large baths and a theatre. Where the Samnite city stood, with its own coinage in the 4th century BC, is not known."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Allifae lies at the foot of the Monte Matese [S1]; the walls of the Roman town enclose remains of large baths [S3]; the walls of the Roman town enclose remains of a theatre [S3]; there was a Samnite city [S1, S3]; the Samnite city had its own coinage in the 4th century BC [S3]; where the Samnite city stood is not known (statement of the unknown) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Allifae was an ancient town of Italy [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; Allifae lay below (at the foot of) the Monte Matese [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; There was a Roman town of Allifae with walls [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; The walls of Roman Allifae enclose the remains of large baths [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; The walls of Roman Allifae enclose the remains of a theatre [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; Allifae was a Samnite city [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; The Samnite city had its own coinage in the 4th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]; The location of the Samnite city is not known [SUPPORTED: https://en.wikipedia.org/wiki/Allifae]"}]'::jsonb),
    ('c2d5c319-78e7-415e-8b15-a27b4bd30611'::uuid, 'card_description', 'Dedicated around 4–7 AD, the Maison Carrée in Nîmes is among the most complete temples surviving in former imperial territory. Thomas Jefferson modeled the Virginia State Capitol directly on it.', 'The Maison Carré in Nîmes was dedicated or rededicated in about 4 to 7 AD to Gaius and Lucius, grandsons of Augustus who both died young. In medieval times their inscription was removed.', 'teaser-card-s030:c2d5c319-78e7-415e-8b15-a27b4bd30611:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '72f6f5f3c709016de91786a7e4255883fc1c7ad8a5c2dd9abc1cabdfb50ca992|a02c778371c3f27711ca060900e783212c6cd2305906ef097fd16bc8d268b8a1|a02c778371c3f27711ca060900e783212c6cd2305906ef097fd16bc8d268b8a1', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Maison Carré in Nîmes was dedicated or rededicated in about 4 to 7 AD to Gaius and Lucius, grandsons of Augustus who both died young. In medieval times their inscription was removed."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Maison Carré is in Nîmes [S1]; it was dedicated or rededicated in about 4 to 7 AD [S3]; the dedication was to Gaius and Lucius [S3]; Gaius and Lucius were grandsons of Augustus [S3]; Gaius and Lucius both died young [S3]; the inscription dedicating the temple to them was removed in medieval times [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Maison Carree is an ancient Roman temple in Nimes, France (central claim: the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Maison_Carr%C3%A9e]; It was dedicated or rededicated in about 4 to 7 AD [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Maison_Carr%C3%A9e]; The dedication was to Gaius and Lucius (Caesar) [SUPPORTED: https://en.wikipedia.org/wiki/Maison_Carr%C3%A9e]; Gaius and Lucius were grandsons of Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Maison_Carr%C3%A9e]; Gaius and Lucius both died young [SUPPORTED: https://en.wikipedia.org/wiki/Maison_Carr%C3%A9e]; The inscription (dedicating the temple to Gaius and Lucius) was removed in medieval times [SUPPORTED: https://en.wikipedia.org/wiki/Maison_Carr%C3%A9e]"}]'::jsonb),
    ('c2f1098e-8939-4ed4-abe3-61b70bd073b3'::uuid, 'card_description', 'An Iron Age earthwork from 700-42 BC enclosing a forest clearing. Local legend claims Boudica made her last stand here against the Romans, though evidence is thin.', 'In Epping Forest lie the remains of Ambresbury Banks, an Iron Age hill fort enclosing roughly 5 hectares. In 1971 a metal detector turned up 2 Iron Age gold coins near its banks.', 'teaser-card-s030:c2f1098e-8939-4ed4-abe3-61b70bd073b3:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '9d6a015866e533de55ab33cdceeb426b02f619cff6d548bbf2e3f2fdb0db4476|20aa125af39b67bfdd2f4ba491427cd65e8c4f148f09f9d7141d89e694e035f8|20aa125af39b67bfdd2f4ba491427cd65e8c4f148f09f9d7141d89e694e035f8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Epping Forest lie the remains of Ambresbury Banks, an Iron Age hill fort enclosing roughly 5 hectares. In 1971 a metal detector turned up 2 Iron Age gold coins near its banks."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in Epping Forest [S1]; the remains are those of an Iron Age hill fort [S1]; the fort encloses roughly 5 hectares [S6]; in 1971 two Iron Age gold coins were found [S5]; the coins were found with a metal detector [S5]; the coins were found near the Banks [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ambresbury Banks is the remains of a hill fort (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; It lies in Epping Forest [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; The fort encloses roughly 5 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; A find was made in 1971 [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; The find was 2 coins [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; The coins were Iron Age gold coins [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; The coins were found with a metal detector [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]; The coins were found near the banks of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Ambresbury_Banks]"}]'::jsonb),
    ('c35b1649-9442-4195-9604-4481ce65ffbf'::uuid, 'card_description', 'The main gate of Diocletian''s Palace, built in the 4th century AD with elaborate decoration befitting an emperor''s entrance. It was sealed in the Middle Ages and reopened in modern times.', 'Diocletian probably entered his palace in Split through the Golden Gate after abdicating on 1 May 305. Above its lintel, an arch of 19 stone blocks crowns what was once the main gate.', 'teaser-card-s030:c35b1649-9442-4195-9604-4481ce65ffbf:card_description', 'teaser-card-s030 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '1f721f3618d6ee5a1262900a8aaf48d42e84b5dd2b412de638d6330f3e9b1585|207f820f01d8712e63b5ae70a3e2056413ab3d35930b7e75a9466fe4a1e70a9e|207f820f01d8712e63b5ae70a3e2056413ab3d35930b7e75a9466fe4a1e70a9e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Diocletian probably entered his palace in Split through the Golden Gate after abdicating on 1 May 305. Above its lintel, an arch of 19 stone blocks crowns what was once the main gate."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Diocletian probably entered his palace through the Golden Gate (hedged) [S5]; the palace is in Split [S1, S2]; he entered after abdicating [S5]; the abdication was on 1 May 305 [S5]; above the gate''s lintel is an arch [S8]; the arch is composed of 19 stone blocks [S8]; the gate was once the main gate of the palace [S2, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Golden Gate is a gate of Diocletian''s Palace, built as its main gate (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; Diocletian''s Palace is in Split (Croatia) [SUPPORTED: https://en.wikipedia.org/wiki/Diocletian%27s_Palace]; Diocletian probably entered the palace through the Golden Gate [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; Diocletian abdicated (the entry came after the abdication) [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; The abdication was on 1 May 305 [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; Above the gate''s lintel is an arch [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; The arch is made of 19 blocks [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; The blocks are of stone [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]; The gate was once the main gate of the palace [SUPPORTED: https://en.wikipedia.org/wiki/Golden_Gate_(Diocletian%27s_Palace)]"}]'::jsonb),
    ('c3ed760b-0027-4275-bed0-787ef5d7ef02'::uuid, 'card_description', 'A Cornish headland where Iron Age inhabitants cut a ditch across the narrow land-neck, leaving a central causeway still visible. Round house platforms survive on the eastern section.', 'Rame Head, a coastal headland in southeast Cornwall, was used for an Iron Age promontory fort. Its narrow neck still shows a central causeway, and traces of round house platforms remain.', 'teaser-card-s030:c3ed760b-0027-4275-bed0-787ef5d7ef02:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '32af8f43e44a0469912e2d0b761b854978b3f593d868c894888e746986a8dea0|e13b4f645f0a1f710d7ba0303a35d9a1f30588bbe707fdad2e10755a390c81e2|e13b4f645f0a1f710d7ba0303a35d9a1f30588bbe707fdad2e10755a390c81e2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Rame Head, a coastal headland in southeast Cornwall, was used for an Iron Age promontory fort. Its narrow neck still shows a central causeway, and traces of round house platforms remain."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Rame Head is a coastal headland [S1]; it is in southeast Cornwall [S1]; it was used for an Iron Age promontory fort [S3]; its narrow neck still shows a central causeway [S3]; traces of round house platforms remain [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Rame Head is a headland (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]; The headland is coastal [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Rame_Head]; It is in southeast Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]; The headland was used for a promontory fort [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]; The promontory fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]; The headland has a narrow neck of land [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]; The narrow neck still shows a central causeway [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]; Traces of round house platforms remain [SUPPORTED: https://en.wikipedia.org/wiki/Rame_Head]"}]'::jsonb),
    ('c434e091-07f2-4748-a298-2766e0717bb6'::uuid, 'card_description', 'Settled by 700–550 BC, Igeum-dong shows the earliest firm evidence of chiefdom formation on the peninsula — nearly 950 years before the first state-level societies formed in the region.', 'At Igeum-dong, the 63 burials of a megalithic cemetery are linked by low pavements of rounded river cobbles. The site also holds the two largest raised-floor buildings in Korean prehistory.', 'teaser-card-s030:c434e091-07f2-4748-a298-2766e0717bb6:card_description', 'teaser-card-s030 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '5a91779bbef17eda231369460f476f08fbd05458cbb8c652d90e9033d0c866e9|da54abd9f4c3770c23d42e951d383a349e2a7bb3dda35bfd96186f13808180cd|da54abd9f4c3770c23d42e951d383a349e2a7bb3dda35bfd96186f13808180cd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Igeum-dong, the 63 burials of a megalithic cemetery are linked by low pavements of rounded river cobbles. The site also holds the two largest raised-floor buildings in Korean prehistory."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Igeum-dong has a megalithic cemetery [S5, S6]; the cemetery has 63 burials [S5]; low pavements of rounded river cobbles link the burials [S6]; the site holds two raised-floor buildings that are the largest in Korean prehistory [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Igeum-dong is a prehistoric archaeological site with a megalithic cemetery, in South Korea (central claim: the kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Igeum-dong]; The site has a megalithic cemetery of 63 burials [SUPPORTED: https://en.wikipedia.org/wiki/Igeum-dong]; The burials are linked by low pavements of rounded river cobbles [SUPPORTED: https://en.wikipedia.org/wiki/Igeum-dong]; The site holds the two largest raised-floor buildings in Korean prehistory [SUPPORTED: https://en.wikipedia.org/wiki/Igeum-dong]"}]'::jsonb),
    ('c4d2251b-b64a-4615-a6f9-5a71ff6f3955'::uuid, 'card_description', 'A 400-1200 AD village of around 90 circular stone foundations spread across a hillside. Circular architecture is distinctive — most Mesoamerican buildings used rectangular plans.', 'A stairway of more than 80 steps on the western hillside was the original way into Balcon de Montezuma, where over 70 circular structures are grouped into two small semi-circular plazas.', 'teaser-card-s030:c4d2251b-b64a-4615-a6f9-5a71ff6f3955:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'a8ea22bfa54d856d992b97d07862e95f82232755d4a1707e8d94d8004c218d60|0c169980a398cf9124e139c9517c651490171a30d98ecece31f69125b02e10cd|0c169980a398cf9124e139c9517c651490171a30d98ecece31f69125b02e10cd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A stairway of more than 80 steps on the western hillside was the original way into Balcon de Montezuma, where over 70 circular structures are grouped into two small semi-circular plazas."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "a stairway of more than 80 steps [S3]; the stairway is on the western hillside [S3]; the stairway was the original entrance to the site [S3]; the site has over 70 circular structures [S4]; the structures are grouped into two small semi-circular plazas [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Balcon de Montezuma is an archaeological site in Mexico (state of Tamaulipas) [SUPPORTED: https://en.wikipedia.org/wiki/Balc%C3%B3n_de_Montezuma]; The site is a settlement (a village of house bases), not a temple or fort [SUPPORTED: https://en.wikipedia.org/wiki/Balc%C3%B3n_de_Montezuma]; A stairway of more than 80 steps was the original way into the site [SUPPORTED: https://en.wikipedia.org/wiki/Balc%C3%B3n_de_Montezuma]; The stairway is on the western hillside [SUPPORTED: https://en.wikipedia.org/wiki/Balc%C3%B3n_de_Montezuma]; The site has over 70 circular structures [SUPPORTED: https://en.wikipedia.org/wiki/Balc%C3%B3n_de_Montezuma]; The circular structures are grouped into two small semi-circular plazas [SUPPORTED: https://en.wikipedia.org/wiki/Balc%C3%B3n_de_Montezuma]"}]'::jsonb),
    ('c548194d-9265-44f0-bba7-13fa0f9835a8'::uuid, 'card_description', 'The Citânia was constructed on the top of the Santa Luzia hill, overseeing the Lima River''s delta and is protected by three lines of walls, towers, and two moats.', 'Atop a hill over the Lima River''s delta, the Citânia de Santa Luzia is guarded by three lines of walls, towers and two moats. Its innermost walls enclose a single circular house.', 'teaser-card-s030:c548194d-9265-44f0-bba7-13fa0f9835a8:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '6c334c86972e7a756082790846653eed90145c9b88f113aa2d295e89448f4908|95ac0522ca147b876c719e786f31ef730963754e7c77cf080c844622ecdd3582|95ac0522ca147b876c719e786f31ef730963754e7c77cf080c844622ecdd3582', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop a hill over the Lima River''s delta, the Citânia de Santa Luzia is guarded by three lines of walls, towers and two moats. Its innermost walls enclose a single circular house."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site stands atop a hill [S4]; the hill overlooks the Lima River''s delta [S4]; it is protected by three lines of walls [S4]; it is protected by towers [S4]; it is protected by two moats [S4]; the innermost walls enclose a single circular house [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Citania de Santa Luzia is a fortified Castro-culture settlement (hillfort) in Viana do Castelo, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Santa_Luzia]; It stands atop a hill (Santa Luzia hill) [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Santa_Luzia]; The hill overlooks the Lima River''s delta [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Santa_Luzia]; It is guarded by three lines of walls [SUPPORTED: https://culturaportugal.gov.pt/pt/conhecer/local/_drcnorte/citania-de-santa-luzia/]; The walls are complemented by towers [SUPPORTED: https://culturaportugal.gov.pt/pt/conhecer/local/_drcnorte/citania-de-santa-luzia/]; It is guarded by two moats [SUPPORTED: https://culturaportugal.gov.pt/pt/conhecer/local/_drcnorte/citania-de-santa-luzia/]; Its innermost walls enclose a house [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Santa_Luzia]; That house inside the innermost walls is the only one (a single house) and is circular [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Santa_Luzia]"}]'::jsonb),
    ('c59b8485-583b-4c64-8d5b-61e046ed3437'::uuid, 'card_description', 'Probably around 3000 BC a Class II henge was constructed with the hilltop being surrounded by a bank outside a ditch about 12 ft wide cut over 3 ft into the rock.', 'With views from coast to coast, Cairnpapple Hill was a ritual site for around 4,000 years. Under its cairn lay traces of at least one burial, with wooden objects, perhaps a mask and club.', 'teaser-card-s030:c59b8485-583b-4c64-8d5b-61e046ed3437:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '205484edc8e5ee2df3e4ad0a49497b195b71292aa720015382d2c9e98fa22c95|434523b5fb9dc690c69cf8ba6ba5e036840a2fc2402c3ec3e6eab400dc977627|434523b5fb9dc690c69cf8ba6ba5e036840a2fc2402c3ec3e6eab400dc977627', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "With views from coast to coast, Cairnpapple Hill was a ritual site for around 4,000 years. Under its cairn lay traces of at least one burial, with wooden objects, perhaps a mask and club."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the hill has views from coast to coast [S1]; it was a ritual site for around 4,000 years [S2]; a cairn stands on the hill [S6, S7]; under the cairn were traces of at least one burial [S7]; the burial had wooden objects [S7]; the wooden objects were perhaps a mask and club (hedged) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cairnpapple Hill is a hill in central lowland Scotland that served as a ritual site [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; The hill offers views from coast to coast [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; It was a ritual site [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; It was a ritual site for around 4,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; The site has a cairn with a burial under it [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; Under the cairn lay traces of at least one burial (not more than traces) [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; The burial came with wooden objects [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]; The wooden objects were perhaps a mask and a club (uncertain identification) [SUPPORTED: https://en.wikipedia.org/wiki/Cairnpapple_Hill]"}]'::jsonb),
    ('c5d2dfc5-1a50-4b7c-a3f1-6879aa5b1c67'::uuid, 'card_description', 'Four tall standing stones arranged in ascending height across 13.4 metres -- the largest stone row of over 80 in the southwest. The tallest stone stands 3.4 metres.', 'Castlenalacht Stone Row, the largest of over 80 stone rows in south-west Ireland, sets four tall stones in rising height across 13.4 m on a Cork hilltop. Their precise function is unknown.', 'teaser-card-s030:c5d2dfc5-1a50-4b7c-a3f1-6879aa5b1c67:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '0031f2787bfbba9630acf7d43cab343ad706e58752343ac34705c43ec47f9a4e|75ecce4ea35cee4341ccfd8aea074ffdcc48da05b8e60e5d92b80d72eab6bcc8|75ecce4ea35cee4341ccfd8aea074ffdcc48da05b8e60e5d92b80d72eab6bcc8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Castlenalacht Stone Row, the largest of over 80 stone rows in south-west Ireland, sets four tall stones in rising height across 13.4 m on a Cork hilltop. Their precise function is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the row is the largest of the over 80 stone rows in south-west Ireland [S2]; it has four tall stones [S1]; the stones rise in height [S3]; they span 13.4 m [S3]; it stands on a hilltop in County Cork [S1]; the precise function of the stone rows is unknown (statement of the unknown) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Castlenalacht Stone Row is a stone row (alignment) in County Cork, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; The row consists of four tall stones [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; It stands on a hilltop in Cork [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; It is the largest of the stone rows in south-west Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; There are over 80 stone rows in south-west Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; The four stones are set in rising (ascending) order of height [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; The row spans 13.4 m [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]; Their precise function is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Castlenalacht_Stone_Row]"}]'::jsonb),
    ('c70dabb7-6915-4def-961f-14f0f7d8e30b'::uuid, 'card_description', 'A 5-hectare Iron Age hillfort guarded by a single earthen bank. A Bronze Age barrow nearby was later reshaped into a Norman beacon mound.', 'On Dundon Hill Hillfort, an Iron Age hillfort in Compton Dundon, Somerset, the ground gave up flint flakes and Bronze Age and Iron Age pottery, finds now kept in the Museum of Somerset.', 'teaser-card-s030:c70dabb7-6915-4def-961f-14f0f7d8e30b:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '8e59844b4533a6b294b967cebb5f89caaf49468929b87f633829713f62778f4d|174014455f08b3b5fbd3468312a21841236ff7ab69987b22cab1a28e5e2d4c7c|174014455f08b3b5fbd3468312a21841236ff7ab69987b22cab1a28e5e2d4c7c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Dundon Hill Hillfort, an Iron Age hillfort in Compton Dundon, Somerset, the ground gave up flint flakes and Bronze Age and Iron Age pottery, finds now kept in the Museum of Somerset."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is an Iron Age hillfort [S1]; it lies in Compton Dundon, Somerset [S1]; flint flakes have been found [S3]; Bronze Age pottery has been found [S3]; Iron Age pottery has been found [S3]; the finds are now kept in the Museum of Somerset [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dundon Hill Hillfort is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]; It lies in Compton Dundon, Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]; Flint flakes were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]; Bronze Age pottery was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]; Iron Age pottery was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]; The finds are now kept in the Museum of Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort]"}]'::jsonb),
    ('c720b595-63d5-4f41-ba14-47ebf79c6098'::uuid, 'card_description', 'The first inscriptions in Amantia appear in the 4th century BC, during the Hellenistic era.', 'Above the Vjosë valley, a walled enclosure roughly 2,100 metres long surrounded the town of Amantia, where a temple dedicated to Aphrodite, a theatre and a stadium have been found.', 'teaser-card-s030:c720b595-63d5-4f41-ba14-47ebf79c6098:card_description', 'teaser-card-s030 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f197be2e7bd49cda4d6e64f72178f8200b63f4a84466cd7b34efc416561a6f21|2a1df1ff1ccb7841badd152ce8556170cb217a2f8b8f9a5d60ec0ac2e6078d96|2a1df1ff1ccb7841badd152ce8556170cb217a2f8b8f9a5d60ec0ac2e6078d96', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Above the Vjosë valley, a walled enclosure roughly 2,100 metres long surrounded the town of Amantia, where a temple dedicated to Aphrodite, a theatre and a stadium have been found."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "above the Vjosë valley [S3]; walled enclosure roughly 2,100 metres long surrounded the town [S6]; temple dedicated to Aphrodite found [S4]; a theatre found [S4]; a stadium found [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Amantia was an ancient city/town (a settlement) in Albania, in a defensive position above the Vjosë valley [SUPPORTED: https://en.wikipedia.org/wiki/Amantia]; Amantia was an ancient city [SUPPORTED: https://en.wikipedia.org/wiki/Amantia]; The town was surrounded by a walled enclosure roughly 2,100 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Amantia]; A temple dedicated to Aphrodite has been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Amantia]; A theatre has been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Amantia]; A stadium has been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Amantia]"}]'::jsonb),
    ('c72fb36a-0726-4975-9d7a-edc5bd59a66f'::uuid, 'card_description', 'During the 1970s interest in Acaray increased, and the first work by archaeologists was initiated at the fortress.', 'In the Huaura River Valley on Peru''s near north coast lies Acaray, which Hans Horkheimer in 1962 deemed a true fortress, unlike neighbouring Paramonga, whose defensive nature is questioned.', 'teaser-card-s030:c72fb36a-0726-4975-9d7a-edc5bd59a66f:card_description', 'teaser-card-s030 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'fc48f1a8f36813f6ded6683a4b13877705b9ba8ffd2df26e4a4a86f8a1b321c6|a6c1774012c1a72a0afad9024f3ed4d415189a639a854dab5068dc52d0f177bd|a6c1774012c1a72a0afad9024f3ed4d415189a639a854dab5068dc52d0f177bd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Huaura River Valley on Peru''s near north coast lies Acaray, which Hans Horkheimer in 1962 deemed a true fortress, unlike neighbouring Paramonga, whose defensive nature is questioned."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Acaray lies in the Huaura River Valley [S1]; it lies on Peru''s near north coast [S1]; Hans Horkheimer deemed Acaray a true fortress [S3]; he did so in 1962, the year he wrote about Acaray [S2, S3]; Paramonga is a neighbouring site [S3]; Horkheimer contrasted Acaray with Paramonga [S3]; Paramonga''s defensive nature is questioned [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Acaray is an archaeological site, a fortress (hilltop fort) [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; Acaray lies in the Huaura River Valley [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; Acaray is in Peru, on the near north coast [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; Hans Horkheimer wrote about Acaray in 1962 [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; Horkheimer deemed Acaray a true fortress [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; Paramonga is a neighbouring site of Acaray [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; The defensive nature of Paramonga has been questioned [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]; Horkheimer contrasted Acaray''s true-fortress status with Paramonga (unlike Paramonga) [SUPPORTED: https://en.wikipedia.org/wiki/Acaray]"}]'::jsonb),
    ('c7d33a59-e6ed-46e1-ad3f-5598b699727b'::uuid, 'card_description', 'Herefordshire Beacon''s shape is entirely determined by the terraced Iron Age earthworks, compared to a giant wedding cake. A Norman castle was added later atop this 2nd-century BC fortification.', 'Atop Herefordshire Beacon in the Malvern Hills, British Camp''s earthworks have been compared to a giant wedding cake: an Iron Age hill fort thought first built in the 2nd century BC.', 'teaser-card-s030:c7d33a59-e6ed-46e1-ad3f-5598b699727b:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '8bd461285bf6c00953967aa0128c0a893c440530fdd565b1af8da4fdabd7ffd5|3bd7cf1999a87dd98ac0fb6547974bf67404f35de5eb9e56c38f486635bd5dc9|3bd7cf1999a87dd98ac0fb6547974bf67404f35de5eb9e56c38f486635bd5dc9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop Herefordshire Beacon in the Malvern Hills, British Camp''s earthworks have been compared to a giant wedding cake: an Iron Age hill fort thought first built in the 2nd century BC."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site sits atop Herefordshire Beacon [S1]; Herefordshire Beacon is in the Malvern Hills [S1]; the earthworks have been compared to a giant wedding cake [S3]; British Camp is an Iron Age hill fort [S1]; the fort is thought to have been first built in the 2nd century BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "British Camp is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/British_Camp]; It lies atop Herefordshire Beacon [SUPPORTED: https://en.wikipedia.org/wiki/British_Camp]; Herefordshire Beacon is in the Malvern Hills [SUPPORTED: https://en.wikipedia.org/wiki/Herefordshire_Beacon]; British Camp has earthworks [SUPPORTED: https://en.wikipedia.org/wiki/British_Camp]; The earthworks have been compared to a giant wedding cake [SUPPORTED: https://en.wikipedia.org/wiki/British_Camp]; The fort is thought to have been first built in the 2nd century BC [SUPPORTED: https://en.wikipedia.org/wiki/British_Camp]"}]'::jsonb),
    ('c7e6cd9c-cfb2-408a-b510-b33e5db5c0a1'::uuid, 'card_description', 'Four artificial burial caves from 3000 BC, also called the Palmela Caves. Human remains inside span hundreds of years of continuous communal burial.', 'Cut into soft limestone with stone tools around 3000 BCE, the Artificial Caves of Casal do Pardo are four Neolithic tombs that yielded arrowheads, limestone idols and bone buttons.', 'teaser-card-s030:c7e6cd9c-cfb2-408a-b510-b33e5db5c0a1:card_description', 'teaser-card-s030 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '994e1762597b2132c3bbe7b3a8a15a5309188b3cca1803a23647e8f14403c9ec|c86799d87ec1f707609f735ed16995cb9469c08c2845a5cf6b63e171fc8256ef|c86799d87ec1f707609f735ed16995cb9469c08c2845a5cf6b63e171fc8256ef', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cut into soft limestone with stone tools around 3000 BCE, the Artificial Caves of Casal do Pardo are four Neolithic tombs that yielded arrowheads, limestone idols and bone buttons."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the caves are cut into soft limestone [S4]; they were cut with stone tools [S4]; they were dug around 3000 BCE [S5]; there are four caves [S1, S4]; they are Neolithic tombs [S1]; excavation yielded arrowheads [S7]; excavation yielded limestone idols [S7]; excavation yielded bone buttons [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Artificial Caves of Casal do Pardo are four Neolithic tombs [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; The site is in Portugal (Palmela municipality, Setubal District) [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; The tombs are cut into soft limestone [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; They were cut with stone tools [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; The caves were dug out around 3000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; Excavations yielded arrowheads [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; Excavations yielded limestone idols [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]; Excavations yielded bone buttons [SUPPORTED: https://en.wikipedia.org/wiki/Artificial_caves_of_Casal_do_Pardo]"}]'::jsonb),
    ('c80bf1e4-215a-440d-9e2e-848c40348037'::uuid, 'card_description', NULL, 'In a collapsed cave overlooking the Krapinica River, the Krapina Neanderthal Site gave up the largest known haul of human skeletal remains from any Upper Pleistocene site.', 'teaser-card-s030:c80bf1e4-215a-440d-9e2e-848c40348037:card_description', 'teaser-card-s030 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '888dc867f3a28aaa7a3a9210f49916fc99e68ee73342f80b7e9a376035672623|f4f51fd4dfd78f07529ea89c61619b97f7787ccaaf12da5e04bc7d0fcb2ca33e|f4f51fd4dfd78f07529ea89c61619b97f7787ccaaf12da5e04bc7d0fcb2ca33e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In a collapsed cave overlooking the Krapinica River, the Krapina Neanderthal Site gave up the largest known haul of human skeletal remains from any Upper Pleistocene site."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in a collapsed cave [S4]; it overlooks the Krapinica River [S4]; it is the largest known recovery of human skeletal remains from any Upper Pleistocene site [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Krapina Neanderthal Site is a Paleolithic archaeological site, a collapsed cave site [SUPPORTED: https://en.wikipedia.org/wiki/Krapina_Neanderthal_site]; The site is in Croatia, near Krapina [SUPPORTED: https://en.wikipedia.org/wiki/Krapina_Neanderthal_site]; The site is located in a collapsed cave [SUPPORTED: https://en.wikipedia.org/wiki/Krapina_Neanderthal_site]; The cave overlooks the Krapinica River [SUPPORTED: https://en.wikipedia.org/wiki/Krapina_Neanderthal_site]; The site yielded human skeletal remains (Neanderthal) [SUPPORTED: https://en.wikipedia.org/wiki/Krapina_Neanderthal_site]; Krapina is the largest known recovery of human skeletal remains from any Upper Pleistocene site [SUPPORTED: https://en.wikipedia.org/wiki/Krapina_Neanderthal_site]"}]'::jsonb),
    ('c81634b0-969c-484b-aa1f-5b5926e05fd3'::uuid, 'card_description', 'The spectacular landscape of Las Médulas resulted from ruina montium, a Roman mining technique described by Pliny the Elder in 77 AD.', 'Roman miners undermined mountains with large quantities of water to carve Las Médulas, the largest open-pit gold mine in the entire Roman Empire, now a spectacular landscape.', 'teaser-card-s030:c81634b0-969c-484b-aa1f-5b5926e05fd3:card_description', 'teaser-card-s030 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '1b5575aa02da6bc9be643df11e44d4f059fab175dfc641fbd26af8e512c81e6a|4762e96b55d456f6c06c1bc08e65878ea8bc2663a4214811e34cfcd297427408|4762e96b55d456f6c06c1bc08e65878ea8bc2663a4214811e34cfcd297427408', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Roman miners undermined mountains with large quantities of water to carve Las Médulas, the largest open-pit gold mine in the entire Roman Empire, now a spectacular landscape."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Roman miners worked the site [S2, S3]; they undermined mountains with large quantities of water [S4]; this technique produced the landscape of Las Médulas [S3]; Las Médulas is the largest open-pit gold mine in the entire Roman Empire [S2]; it is a spectacular landscape [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Las Médulas is a gold-mining site (a mine) in El Bierzo, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Las_M%C3%A9dulas]; Las Médulas was the largest open-pit gold mine in the entire Roman Empire [SUPPORTED: https://en.wikipedia.org/wiki/Las_M%C3%A9dulas]; Roman miners undermined mountains with large quantities of water [SUPPORTED: https://en.wikipedia.org/wiki/Las_M%C3%A9dulas]; The landscape of Las Médulas was carved by the Roman mining (the Romans made it) [SUPPORTED: https://en.wikipedia.org/wiki/Las_M%C3%A9dulas]; Las Médulas is now a spectacular landscape (a protected cultural landscape) [SUPPORTED: https://en.wikipedia.org/wiki/Las_M%C3%A9dulas]"}]'::jsonb),
    ('c82e8c63-783d-4d7b-aead-69052b6a04a2'::uuid, 'card_description', 'Three Bronze Age stone rows on Dartmoor, each ending with a menhir. The tallest reaches 4.3 meters — the largest standing stone on all of Dartmoor.', 'At Drizzlecombe on Dartmoor, three principal stone rows each have a barrow and a terminal menhir. The tallest menhir, 14 ft high and the largest on Dartmoor, was re-erected in 1893.', 'teaser-card-s030:c82e8c63-783d-4d7b-aead-69052b6a04a2:card_description', 'teaser-card-s030 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '47589721201af0f144fd9d988fb0ad8a6219a83d8d613e39c77c3a7783374f73|8fe75c03907a2d2d8166531015fee0b8896ac1e3510aced962a2fa608077469b|8fe75c03907a2d2d8166531015fee0b8896ac1e3510aced962a2fa608077469b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Drizzlecombe on Dartmoor, three principal stone rows each have a barrow and a terminal menhir. The tallest menhir, 14 ft high and the largest on Dartmoor, was re-erected in 1893."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Drizzlecombe is on Dartmoor [S1]; there are three principal stone rows [S2]; each row has an associated barrow [S2]; each row has a terminal menhir [S2]; the tallest menhir is 14 ft high [S4]; it is the largest menhir on Dartmoor [S4]; it was re-erected in 1893 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Drizzlecombe is a site on Dartmoor with Bronze Age stone rows, cairns and menhirs (a prehistoric stone row complex) [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; Drizzlecombe has three principal stone rows [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; Each of the three principal stone rows has a barrow [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; Each of the three principal stone rows has a terminal menhir [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; The tallest menhir is 14 ft high [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; The tallest menhir is the largest on Dartmoor [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; The tallest menhir was re-erected (it had fallen and was set upright again) [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]; The re-erection of the tallest menhir took place in 1893 [SUPPORTED: https://en.wikipedia.org/wiki/Drizzlecombe]"}]'::jsonb),
    ('c8af8070-bdd2-46a4-b651-a87fadb09bfe'::uuid, 'card_description', 'Enclosing 1.6 hectares with a single ditch and inner rampart in Hampshire, this fort sits where Grim''s Ditch — a mysterious linear earthwork — also runs. Their relationship remains unexplained.', 'West of Rockbourne in Hampshire, Knoll Camp rings about four acres with a single ditch and an inner rampart, an Iron Age hill fort where traces of a counter scarp bank remain.', 'teaser-card-s030:c8af8070-bdd2-46a4-b651-a87fadb09bfe:card_description', 'teaser-card-s030 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'f7c38f19c4b60e34814c3591d5f23eaa240bc3744b90c420740b238109a446d8|88fab3d8b21816d25d43a0affc6fb38580f1a0f4a617e1cbfae9d6052f3d9750|88fab3d8b21816d25d43a0affc6fb38580f1a0f4a617e1cbfae9d6052f3d9750', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "West of Rockbourne in Hampshire, Knoll Camp rings about four acres with a single ditch and an inner rampart, an Iron Age hill fort where traces of a counter scarp bank remain."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies west of Rockbourne [S5]; it is in Hampshire [S1, S5]; the circular earthwork encloses about four acres [S2]; it has a single ditch [S3]; it has an inner rampart [S3]; it is an Iron Age hill fort [S1]; traces of a counter scarp bank remain [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Knoll Camp is a hill fort (a fortified enclosure) [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; Knoll Camp dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; Knoll Camp is in Hampshire [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; Knoll Camp lies west of Rockbourne [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; The fort encloses about four acres, in a ring (circular earthwork) [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; The fort has a single ditch [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; The fort has an inner rampart [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]; Traces of a counter scarp bank remain [SUPPORTED: https://en.wikipedia.org/wiki/Knoll_Camp]"}]'::jsonb),
    ('c8d355dd-e6f9-44bd-b73b-a23f9e550590'::uuid, 'card_description', 'Said to be the tomb of Virgil, Rome''s greatest poet, at the entrance to a Roman tunnel. The site became a medieval pilgrimage destination surrounded by legends of magic.', 'At the mouth of the old Roman tunnel of the Crypta Neapolitana in Naples lies Virgil''s Tomb, said to hold the poet, where pilgrims came for many centuries, Petrarch and Boccaccio among them.', 'teaser-card-s030:c8d355dd-e6f9-44bd-b73b-a23f9e550590:card_description', 'teaser-card-s030 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '3c1ad52df11d6401087af054277e6fe1d8cdb82746e19de21a00818a88411765|e4663cf3f0a6722958c48f6e4f48ac58fe44ffd91a8276abd444aed3c2848869|e4663cf3f0a6722958c48f6e4f48ac58fe44ffd91a8276abd444aed3c2848869', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the mouth of the old Roman tunnel of the Crypta Neapolitana in Naples lies Virgil''s Tomb, said to hold the poet, where pilgrims came for many centuries, Petrarch and Boccaccio among them."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the tomb is at the entrance to the old Roman tunnel, the Crypta Neapolitana [S2]; it is in Naples [S1, S2]; it is said to be the tomb of the poet Virgil [S1]; it was a place of pilgrimage for many centuries [S3]; Petrarch and Boccaccio were among those who visited [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Virgil''s Tomb is a Roman burial vault (a tomb) in Naples [SUPPORTED: https://en.wikipedia.org/wiki/Virgil%27s_tomb]; It lies at the mouth (entrance) of the old Roman tunnel known as the Crypta Neapolitana [SUPPORTED: https://en.wikipedia.org/wiki/Virgil%27s_tomb]; The Crypta Neapolitana is an ancient Roman tunnel at Naples [SUPPORTED: https://en.wikipedia.org/wiki/Crypta_Neapolitana]; The tomb is said (by tradition) to hold the poet Virgil [SUPPORTED: https://en.wikipedia.org/wiki/Virgil%27s_tomb]; Pilgrims came to Virgil''s tomb for many centuries, Petrarch and Boccaccio among them [SUPPORTED: https://en.wikipedia.org/wiki/Virgil%27s_tomb]"}]'::jsonb),
    ('c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359'::uuid, 'card_description', 'A 100-room Minoan settlement from the Early Bronze Age perched atop a steep hill. Two weaving looms found among the ruins hint at a textile-producing community.', 'Atop a steep hill on southern Crete, with excellent views of the coast, lies Fournou Korifi, a Minoan settlement used only in the Early Minoan II period, where two weaving looms were found.', 'teaser-card-s030:c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359:card_description', 'teaser-card-s030 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '515697f644706170439305b4beeaeaee98d638e6ea919a1950bfb793fff6dba4|a27e824c9cdec35856f35ce510034dd2c209ae2a38245773269c352ce962de57|a27e824c9cdec35856f35ce510034dd2c209ae2a38245773269c352ce962de57', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop a steep hill on southern Crete, with excellent views of the coast, lies Fournou Korifi, a Minoan settlement used only in the Early Minoan II period, where two weaving looms were found."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site stands at the top of a steep hill [S2]; it is on southern Crete [S1]; it has excellent views of the coast [S2]; it is a Minoan settlement [S1]; it was used only in the Early Minoan II period [S4]; two weaving looms were found [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Fournou Korifi is a Minoan settlement [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]; Fournou Korifi is on southern Crete (Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]; It lies atop a steep hill [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]; The hilltop has excellent views of the coast [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]; The settlement was used only in the Early Minoan II period [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]; Weaving looms were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]; The number of looms found was two [SUPPORTED: https://en.wikipedia.org/wiki/Fournou_Korifi]"}]'::jsonb),
    ('c967f1ad-c198-4e0c-88da-c0f591af9e43'::uuid, 'card_description', 'A colony planted by Alexander the Great at a key junction in the Hindu Kush foothills. Coins of later Greco-Bactrian kings show Zeus was the city''s patron deity.', 'In the foothills of the Hindu Kush, once called the Caucasus, Alexander the Great founded Alexandria in the Caucasus, later home to a thriving Buddhist community headed by Greek monks.', 'teaser-card-s030:c967f1ad-c198-4e0c-88da-c0f591af9e43:card_description', 'teaser-card-s030 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '85d7b3c927484b7477cec4a05d9cc2fd92dfc49da8a645c4a17679b598bb42b0|6cad72c603d2d5eb6d1c33ca247806a9df5e86c6e06c2ab213106fcfae95e2ce|6cad72c603d2d5eb6d1c33ca247806a9df5e86c6e06c2ab213106fcfae95e2ce', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the foothills of the Hindu Kush, once called the Caucasus, Alexander the Great founded Alexandria in the Caucasus, later home to a thriving Buddhist community headed by Greek monks."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the city lay in the foothills of the Hindu Kush [S3]; the Hindu Kush was once also called the Caucasus [S4]; Alexander the Great founded it [S1, S3]; it later had a thriving Buddhist community [S3, S6]; the community was headed by Greek monks [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Alexandria in the Caucasus was a colony (a settlement) in the southern foothills of the Hindu Kush [SUPPORTED: https://en.wikipedia.org/wiki/Alexandria_in_the_Caucasus]; The Hindu Kush was once called the Caucasus [SUPPORTED: https://en.wikipedia.org/wiki/Alexandria_in_the_Caucasus]; Alexander the Great founded Alexandria in the Caucasus [SUPPORTED: https://en.wikipedia.org/wiki/Alexandria_in_the_Caucasus]; The city was later home to a thriving Buddhist community [SUPPORTED: https://en.wikipedia.org/wiki/Alexandria_in_the_Caucasus]; The Buddhist community was headed by Greek monks [SUPPORTED: https://en.wikipedia.org/wiki/Alexandria_in_the_Caucasus]"}]'::jsonb),
    ('c9ab63ba-44f8-4e52-aec1-2e305191abf6'::uuid, 'card_description', 'Excavations in 1864–65 and 1927–35 found human and animal remains, stone tools, pottery, amber beads, and bronze items within Thor''s Cave and the adjacent Thor''s Fissure Cavern.', 'In a limestone crag of the Manifold Valley, the arch of Thor''s Cave, 10 metres high, opens around 80 metres above the valley bottom; digs found amber beads, bronze items and human remains.', 'teaser-card-s030:c9ab63ba-44f8-4e52-aec1-2e305191abf6:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '6df8823450c5b76de2a91fe2d6486ea7f8951bea81a6e58b42d255b4eef7df52|ff4c858d2e067e7663987651c9c9e412d98dbd037a4a91615b17b906bbb67f09|ff4c858d2e067e7663987651c9c9e412d98dbd037a4a91615b17b906bbb67f09', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In a limestone crag of the Manifold Valley, the arch of Thor''s Cave, 10 metres high, opens around 80 metres above the valley bottom; digs found amber beads, bronze items and human remains."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the cave lies in a limestone crag [S3]; it lies in the Manifold Valley [S1]; its entrance is an arch [S3]; the arch is 10 metres high [S3]; it opens around 80 metres above the valley bottom [S3]; excavations found amber beads [S4]; excavations found bronze items [S4]; excavations found human remains [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Thor''s Cave is a natural cavern in the Manifold Valley, Staffordshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; The cave lies in a limestone crag [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; The cave opens in an arch [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; The arch is 10 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; The arch opens around 80 metres above the valley bottom [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; Excavations at the cave found amber beads [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; Excavations at the cave found bronze items [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]; Excavations at the cave found human remains [SUPPORTED: https://en.wikipedia.org/wiki/Thor%27s_Cave]"}]'::jsonb),
    ('c9b1c7b8-07f9-4d8f-849a-2b8538505160'::uuid, 'card_description', 'The Amphitheatre of Capua was a Roman amphitheatre in the ancient city of Capua, second only to the Colosseum in size and probably the model for it.', 'Second only to the Colosseum in size, the Amphitheatre of Capua was probably its model: 80 travertine arches, each keystone decorated with a bust of a god, on a façade 46 metres high.', 'teaser-card-s030:c9b1c7b8-07f9-4d8f-849a-2b8538505160:card_description', 'teaser-card-s030 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'bb02a533cd3744a71a824d33a798ee8ac75480cc3b1cdb2887563e3ad9ba9715|96668e6e977f7ddd12f3bb2257c6cca42b23b4acedd935a360ce54092b56e34b|96668e6e977f7ddd12f3bb2257c6cca42b23b4acedd935a360ce54092b56e34b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Second only to the Colosseum in size, the Amphitheatre of Capua was probably its model: 80 travertine arches, each keystone decorated with a bust of a god, on a façade 46 metres high."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the amphitheatre was second only to the Colosseum in size [S1]; it was probably the model for the Colosseum [S1, S3]; it had 80 travertine arches [S6]; each arch had a bust of a god in its keystone [S6]; the façade was 46 metres high [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Amphitheatre of Capua was a Roman amphitheatre in ancient Capua (modern Santa Maria Capua Vetere) [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]; It was second only to the Colosseum in size [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]; It was probably the model for the Colosseum [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]; It had 80 arches [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]; The arches were made of travertine [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]; Each arch keystone was decorated with a bust of a god [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]; The facade was 46 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_Capua]"}]'::jsonb),
    ('ca60cec6-9909-4285-bc0f-0fe3f063546d'::uuid, 'card_description', '4th-century BC settlement on the Via Egnatia, linking the Adriatic to Byzantium. Its pass harbour sat on the Macedon–Thrace border, 13–15 km east of modern Kavala.', 'On the Via Egnatia near Thrace''s border, an account names Acontisma an outpost at Macedon''s easternmost limit. In Roman times it was also the eastern boundary of the province of Macedonia.', 'teaser-card-s030:ca60cec6-9909-4285-bc0f-0fe3f063546d:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ddbe4a3a474b2d33ea493fdfb0668bcdfca541b8d5ec8f2f2487f8e24bac63c9|a3cf7e0bf2956f946b3673ce80c6da9d599a9b5f3f1c71364d49795c794e6fd2|a3cf7e0bf2956f946b3673ce80c6da9d599a9b5f3f1c71364d49795c794e6fd2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Via Egnatia near Thrace''s border, an account names Acontisma an outpost at Macedon''s easternmost limit. In Roman times it was also the eastern boundary of the province of Macedonia."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Acontisma lies on the Via Egnatia [S1]; it lies near the border of Thrace [S1]; an account identifies Acontisma as an outpost [S3]; the outpost stood at the easternmost limit of Macedonian territory [S3]; in Roman times it was the eastern boundary of the province of Macedonia [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Acontisma was a settlement (a place) in ancient Macedon [SUPPORTED: https://en.wikipedia.org/wiki/Acontisma]; Acontisma lay on the Via Egnatia [SUPPORTED: https://en.wikipedia.org/wiki/Acontisma]; Acontisma lay near the border of Thrace [SUPPORTED: https://en.wikipedia.org/wiki/Acontisma]; An account of Macedon''s consolidation identifies Acontisma as an outpost at the easternmost limit of Macedon [SUPPORTED: https://en.wikipedia.org/wiki/Acontisma]; In Roman times Acontisma was the eastern boundary of the province of Macedonia [SUPPORTED: https://en.wikipedia.org/wiki/Acontisma]"}]'::jsonb),
    ('cb3119c9-4740-4255-a825-21816d822ff1'::uuid, 'card_description', 'The largest temple in Kharga Oasis, and the only surviving Saite-Persian period structure. Its sanctuary depicts hundreds of deities.', 'Its city now lies under the crops, yet the Temple of Hibis endures, the best preserved temple of the Kharga Oasis, its wall decoration credited to the Achaemenid pharaoh Darius I.', 'teaser-card-s030:cb3119c9-4740-4255-a825-21816d822ff1:card_description', 'teaser-card-s030 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '7e070dab6038b204042988d8968fd987d138f66cadd62d0adcff85375af1bac7|7d78a07a18f33edb21bf10d743f8f5c479ca7b56dd6b466f9ae757f855e870d2|7d78a07a18f33edb21bf10d743f8f5c479ca7b56dd6b466f9ae757f855e870d2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its city now lies under the crops, yet the Temple of Hibis endures, the best preserved temple of the Kharga Oasis, its wall decoration credited to the Achaemenid pharaoh Darius I."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the city that once surrounded the temple (Hibis) now lies under the crops [S2]; the Temple of Hibis has survived to the present (endures) [S1]; it is the best preserved temple of the Kharga Oasis [S1]; the temple is in the Kharga Oasis [S1]; its wall decoration is credited to Darius I [S4]; Darius I was an Achaemenid pharaoh [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Temple of Hibis is an ancient Egyptian temple in the Kharga Oasis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hibis]; The Temple of Hibis is the best preserved temple of the Kharga Oasis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hibis]; The temple was once surrounded by a city, Hibis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hibis]; The city of Hibis now lies under the crops [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hibis]; The temple endures, having come down to modern times in relatively good condition [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hibis]; Its wall decoration is credited to the Achaemenid pharaoh Darius I [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hibis]"}]'::jsonb),
    ('cc06fd9c-ce49-49ae-bfb1-4b3b6d05a0bc'::uuid, 'card_description', 'A pre-Aksumite obelisk bearing the oldest known example of the Ge''ez script — the ancestor of the writing system still used in the Horn of Africa today.', 'Pushed over and broken in half long ago, Hawulti, a pre-Aksumite obelisk 5.5 metres high, bears a disk and crescent, probably for the protection of the Sun goddess and the Moon god.', 'teaser-card-s030:cc06fd9c-ce49-49ae-bfb1-4b3b6d05a0bc:card_description', 'teaser-card-s030 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'e95a374115900529410f86f92f05a71bed3070f5532fa31d99aa51abe5a6f2f3|ed7035a855d7c77843b1bddcf923f81f30d93ebe920e12495f3369be45c07a4a|ed7035a855d7c77843b1bddcf923f81f30d93ebe920e12495f3369be45c07a4a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Pushed over and broken in half long ago, Hawulti, a pre-Aksumite obelisk 5.5 metres high, bears a disk and crescent, probably for the protection of the Sun goddess and the Moon god."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the monument was pushed over [S4]; the monument was broken in half [S4]; this happened long ago (in the distant past) [S4]; Hawulti is a pre-Aksumite obelisk [S1]; it is 5.5 metres high [S3]; it bears a disk and crescent [S3]; the disk and crescent were probably meant to place it under the protection of the Sun goddess and the Moon god [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Hawulti is an obelisk (a standing monument) in Matara, Eritrea [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The obelisk is pre-Aksumite (the page also gives Ullendorff''s early-4th-century AD dating, but it calls the monument pre-Aksumite) [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The monument was pushed over long ago [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The monument was broken in half long ago [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The obelisk is 5.5 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The obelisk bears a disk and crescent [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The disk and crescent were meant to place the monument under the protection of the gods (Ullendorff''s reading) [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The disk stands probably for the Sun goddess and the crescent for the Moon god [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]; The protection is only probable (hedged: probably of the Sun goddess and the Moon god, Ullendorff''s belief) [SUPPORTED: https://en.wikipedia.org/wiki/Hawulti_(monument)]"}]'::jsonb),
    ('cc240cba-a746-40f1-9045-b84efedf3e0d'::uuid, 'card_description', 'Atlit Yam is a submerged Pre Pottery Neolithic C archaeological site located 300–400 meters off the coast of Atlit.', 'Submerged 300–400 meters off the coast of Atlit, Atlit Yam yielded fishing hooks, over 6,000 fish remains and at least 90 burials. The buried display poor health, even auditory exotosis.', 'teaser-card-s030:cc240cba-a746-40f1-9045-b84efedf3e0d:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '225af5c68784d2989332a833b1e6ad9e985565953a3cc519b366ea6c6302c2cd|181a4089ba4e5ad0431d8e81c58d9baf2a2fb04da7cd2845fa3b90016b9a17f0|181a4089ba4e5ad0431d8e81c58d9baf2a2fb04da7cd2845fa3b90016b9a17f0', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Submerged 300–400 meters off the coast of Atlit, Atlit Yam yielded fishing hooks, over 6,000 fish remains and at least 90 burials. The buried display poor health, even auditory exotosis."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atlit Yam is submerged [S1]; it lies 300-400 metres off the coast of Atlit [S1]; fishing hooks were recovered [S4]; over 6,000 fish remains were recovered [S5]; at least 90 burials were recovered [S6]; the buried individuals display signs of poor health [S7]; the buried individuals display auditory exotosis [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atlit Yam is a submerged archaeological site (a Pre-Pottery Neolithic C settlement) off the coast of Atlit, Israel [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; The site is submerged [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; The site lies 300-400 meters off the coast [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; Atlit Yam yielded fishing hooks [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; Over 6,000 fish remains were recovered [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; At least 90 burials were recovered [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; The buried individuals display signs of poor health [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]; The poor health includes auditory exotosis [SUPPORTED: https://en.wikipedia.org/wiki/Atlit_Yam]"}]'::jsonb),
    ('cc3b7763-3628-49f7-944c-a7611b5984c3'::uuid, 'card_description', 'Colonia Clunia Sulpicia sat above 1,000 meters in Burgos and served as conventus capital from the 1st century BC. Its theatre and forum dominated the northern plateau of Hispania.', 'More than 1,000 metres up on Alto de Castro lie the remains of Clunia, a Roman city of two public baths, a forum, a theater and a temple to Jupiter, largely abandoned by the Visigothic era.', 'teaser-card-s030:cc3b7763-3628-49f7-944c-a7611b5984c3:card_description', 'teaser-card-s030 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'cc8c370c0ba061a58bde632882863d286613a3c09515717a33336a1c5447cd67|981a5e5b65b7ca15d3ecd5644e42ba3b7c8c071485a77f5a251a1698cad89c30|981a5e5b65b7ca15d3ecd5644e42ba3b7c8c071485a77f5a251a1698cad89c30', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "More than 1,000 metres up on Alto de Castro lie the remains of Clunia, a Roman city of two public baths, a forum, a theater and a temple to Jupiter, largely abandoned by the Visigothic era."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the remains lie on Alto de Castro [S2]; at more than 1,000 metres above sea level [S2]; Clunia was a Roman city [S1]; the city had two public baths [S6]; the city had a forum [S6]; the city had a theater [S6]; the city had a temple to Jupiter [S6]; the city was largely abandoned by the Visigothic era [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Clunia is an ancient Roman city (in the province of Burgos, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; Its remains are in the province of Burgos in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; The remains lie on Alto de Castro [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; Alto de Castro is more than 1,000 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; Clunia had two public baths [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; Clunia had a forum [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; Clunia had a theater [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; Clunia had a temple to Jupiter [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; The city was largely abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]; The city was largely abandoned by the Visigothic era [SUPPORTED: https://en.wikipedia.org/wiki/Clunia]"}]'::jsonb),
    ('cc413994-12b4-4d0c-b143-739d21992542'::uuid, 'card_description', 'The Milreu ruins constitute the most prominent and well preserved evidence of Roman presence in the Algarve.', 'At Estói, the Roman Ruins of Milreu still keep part of a luxurious villa''s once exuberant mosaics, mostly maritime motifs, beside its baths and a temple devoted to a water deity.', 'teaser-card-s030:cc413994-12b4-4d0c-b143-739d21992542:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'd532c0dced9d1ee31059469f6a894d119b14ada90e6acc051346a317356a884b|e1032452982082340eed8bd4a3663613562a6604621c3cf935d89faaf20c2f26|e1032452982082340eed8bd4a3663613562a6604621c3cf935d89faaf20c2f26', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Estói, the Roman Ruins of Milreu still keep part of a luxurious villa''s once exuberant mosaics, mostly maritime motifs, beside its baths and a temple devoted to a water deity."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the ruins are at Estói [S1]; the site still keeps part of the mosaics [S4]; the mosaics were once exuberant [S4]; the mosaics are mostly maritime motifs [S4]; the villa was once luxurious [S3]; the villa had baths (thermae) annexed [S3]; there is a temple among the surrounding buildings [S3]; the temple was devoted to a water deity [S5]; the ruins are of a Roman villa [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Roman Ruins of Milreu are the remains of a Roman villa (villa rustica) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The site is at Estoi (civil parish of Estoi, Faro, Portugal) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The villa was once luxurious [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The villa''s mosaics were once exuberant [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The site still keeps part of the mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The mosaics are mostly maritime motifs [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The villa has baths (annexed thermae) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The site has a temple [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The temple was devoted to a water deity [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]; The temple''s deity was an aquatic one (an imposing building of worship to an aquatic deity south of the villa) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Milreu]"}]'::jsonb),
    ('ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5'::uuid, 'card_description', 'A Minoan palace fresco showing a figure vaulting over a charging bull. The artist had to simultaneously mold and paint wet stucco at height -- an extraordinary feat.', 'A bull-leaping scene on stucco relief in white, reds, blue and black: the Bull-Leaping Fresco fell in flakes from the Minoan palace at Knossos as it was destroyed, probably by earthquake.', 'teaser-card-s030:ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '384a5ad3e4831e937a577bf259beb49d459b7225c7600b7ad261123e645095f4|34d31f7a4f0dd6cd1f292ab6237e1a47c78a8d8215628afd2f9bd013cee0e2dd|34d31f7a4f0dd6cd1f292ab6237e1a47c78a8d8215628afd2f9bd013cee0e2dd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A bull-leaping scene on stucco relief in white, reds, blue and black: the Bull-Leaping Fresco fell in flakes from the Minoan palace at Knossos as it was destroyed, probably by earthquake."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "it shows a bull-leaping scene [S2]; it is on stucco relief [S1, S3]; its colours are white, reds, blue and black [S4]; it fell in flakes from the Minoan palace at Knossos [S1, S6]; it fell as the palace was destroyed [S6]; the destruction was probably by earthquake [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Bull-Leaping Fresco is a stucco panel from the Minoan palace at Knossos (Crete) showing a bull-leaping scene [SUPPORTED: https://en.wikipedia.org/wiki/Bull-Leaping_Fresco]; It shows a bull-leaping scene [SUPPORTED: https://en.wikipedia.org/wiki/Bull-Leaping_Fresco]; The scene is painted on stucco relief [SUPPORTED: https://en.wikipedia.org/wiki/Bull-Leaping_Fresco]; The colours are white, reds, blue and black [SUPPORTED: https://en.wikipedia.org/wiki/Bull-Leaping_Fresco]; The fresco fell in flakes from the palace at Knossos as the palace was destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Bull-Leaping_Fresco]; The destruction of the palace was probably by earthquake [SUPPORTED: https://en.wikipedia.org/wiki/Bull-Leaping_Fresco]"}]'::jsonb),
    ('cf8b5d56-cbc8-4550-bd77-4dc259020bad'::uuid, 'card_description', 'Around 50 meters across in an irregular egg shape, this ~9,000-year-old basalt stone arrangement aligns with equinox and solstice sunset positions — a stone calendar built into the landscape.', 'About 100 basalt stones form an egg-shaped Aboriginal ring, three waist-high stones at its western end: the Wurdi Youang Stone Arrangement, whose purpose, use and age are not known.', 'teaser-card-s030:cf8b5d56-cbc8-4550-bd77-4dc259020bad:card_description', 'teaser-card-s030 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '28731ade61993907eb92d30b878dfac28f98ee2c4f122508ae26c51b3109bcb8|d8728637abe0c5807526e8ea9e148aa8099a897c97f54c25e1ac1534565223c7|d8728637abe0c5807526e8ea9e148aa8099a897c97f54c25e1ac1534565223c7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "About 100 basalt stones form an egg-shaped Aboriginal ring, three waist-high stones at its western end: the Wurdi Youang Stone Arrangement, whose purpose, use and age are not known."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "about 100 basalt stones form the arrangement [S3]; it is egg-shaped [S2]; it is Aboriginal [S1]; it is a ring [S4]; three waist-high stones stand at its western end [S4]; its purpose is not known [S5]; its use is not known [S5]; its age is not known [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Wurdi Youang is an Aboriginal stone arrangement (the kind of place: a ring of stones, not a fort or tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The site is in Australia [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The arrangement has about 100 stones [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The stones are basalt [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The arrangement is egg-shaped [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The arrangement forms a ring [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; There are three such prominent stones [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The three stones are waist-high [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The three stones stand at the western end of the ring [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The purpose and use of the arrangement are not known [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]; The age of the arrangement is not known [SUPPORTED: https://en.wikipedia.org/wiki/Wurdi_Youang]"}]'::jsonb),
    ('cfaf38c0-0365-4841-a42a-1cfc5c45c42d'::uuid, 'card_description', 'A 5th-century AD terraced platform with H-shaped stone blocks cut to millimetre precision. The blocks interlock like puzzle pieces, using no mortar.', 'Near Tiwanaku, the Archaeological site Puma Punku holds a stone block estimated at about 131 tonnes, fragments of five andesite gateways and I-shaped cramps of copper, arsenic and nickel.', 'teaser-card-s030:cfaf38c0-0365-4841-a42a-1cfc5c45c42d:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '375b9263ec04a50b24a30357c3f74ea1b6a04b254e174f4419d7b6ec39df1f02|7d70d8dc2f5b13e03f84a5c42c78b61c921f793d4df864dcdad706f90fedd3a6|7d70d8dc2f5b13e03f84a5c42c78b61c921f793d4df864dcdad706f90fedd3a6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Tiwanaku, the Archaeological site Puma Punku holds a stone block estimated at about 131 tonnes, fragments of five andesite gateways and I-shaped cramps of copper, arsenic and nickel."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is near Tiwanaku [S1]; the largest stone block is estimated to weigh about 131 tonnes [S6]; fragments of five andesite gateways were found [S5]; it has I-shaped cramps [S7]; the cramps are of copper, arsenic and nickel [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Puma Punku is an archaeological site: a terraced platform mound with a monumental complex (not a fort or tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; The site lies near Tiwanaku (Bolivia) [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; The site holds a stone block (the largest block of the complex) [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; The stone block is estimated to weigh about 131 tonnes [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; Fragments of five gateways were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; The gateways are of andesite [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; The site has I-shaped (architectural) cramps [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]; The cramps are of copper, arsenic and nickel (a copper-arsenic-nickel bronze alloy) [SUPPORTED: https://en.wikipedia.org/wiki/Pumapunku]"}]'::jsonb),
    ('d09330b1-d704-4e42-8ad1-39d6a1178704'::uuid, 'card_description', 'The building was constructed on the east side of the Agora or market place of Athens and was used from approximately 150 B.C. onwards for a variety of purposes.', 'Built by King Attalos II of Pergamon, the two-storey Stoa of Attalos in the Agora of Athens was in frequent use until the Heruli burned its woodwork in AD 267. Today it houses a museum.', 'teaser-card-s030:d09330b1-d704-4e42-8ad1-39d6a1178704:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '6bb0d4e36f7ad6e3dc3cd25837b0c36c0434670254774e71c324c677f91a8a39|8e9e687318e6a9bb9d337a26afc20d19e7c2deb6b95c39a085d425462462f5d4|8e9e687318e6a9bb9d337a26afc20d19e7c2deb6b95c39a085d425462462f5d4', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Built by King Attalos II of Pergamon, the two-storey Stoa of Attalos in the Agora of Athens was in frequent use until the Heruli burned its woodwork in AD 267. Today it houses a museum."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "it was built by King Attalos II of Pergamon [S2]; it had two storeys [S4]; it stood in the Agora of Athens [S1]; it was in frequent use until its woodwork was burned [S8]; the Heruli burned its woodwork [S8]; the burning was in AD 267 [S8]; today it houses a museum [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Stoa of Attalos is a stoa (a covered walkway or portico) in the Agora of Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]; It was built by King Attalos II of Pergamon [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]; The stoa had two storeys [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]; The stoa was in frequent use in antiquity until its woodwork was burned [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]; The Heruli burned its woodwork [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]; The burning happened in AD 267 [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]; Today the Stoa houses a museum (the building standing today is the 1952-56 reconstruction, which houses the Museum of the Ancient Agora) [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Attalos]"}]'::jsonb),
    ('d0b9e72f-73a8-4671-a01f-5cafa6e53bf8'::uuid, 'card_description', 'Uruk is the type site for the Uruk period and played a leading role in the early urbanization of Sumer in the mid-4th millennium BC.', 'Writing and monumental architecture emerged in Uruk''s Eanna district, dedicated to Inanna. The Lady of Uruk, a mask from 3100 BC, is one of the earliest representations of the human face.', 'teaser-card-s030:d0b9e72f-73a8-4671-a01f-5cafa6e53bf8:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '0cb6d9589d674875609a56237c5f3926e351233c0b977b3e80bac76b9f573be7|884d21c3757468fd861593148e8f2af02844b461e56c8f8432921936bd28a51c|884d21c3757468fd861593148e8f2af02844b461e56c8f8432921936bd28a51c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Writing and monumental architecture emerged in Uruk''s Eanna district, dedicated to Inanna. The Lady of Uruk, a mask from 3100 BC, is one of the earliest representations of the human face."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "writing emerged in Uruk''s Eanna district [S7]; monumental architecture emerged in Uruk''s Eanna district [S7]; the Eanna district is dedicated to Inanna [S5]; the Lady of Uruk is a mask [S6]; the mask dates from 3100 BC [S6]; it is one of the earliest representations of the human face [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Uruk is an ancient city (an archaeological site, today Warka) [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; Uruk is in Iraq [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; Uruk had an Eanna district [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; Writing emerged in Uruk''s Eanna district [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; Monumental architecture emerged in Uruk''s Eanna district [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; The Eanna district was dedicated to Inanna [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; The Lady of Uruk is a mask (the Mask of Warka) [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; The Lady of Uruk mask dates from 3100 BC [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]; The mask is one of the earliest representations of the human face [SUPPORTED: https://en.wikipedia.org/wiki/Uruk]"}]'::jsonb),
    ('d0f09ee9-6684-44d7-92cb-56c85ea6cb35'::uuid, 'card_description', 'Active 1st–4th centuries AD near Évora in Lusitania, this villa sat at the junction of two Roman roads — to Salacia and Pax Julia. Excavations have uncovered mosaics, coins, and architecture.', 'Next to the Roman road to Salacia, the Roman Villa of Tourega had a large bath with hot and cold water, separate for men and women, and amphorae almost all of which had held fish products.', 'teaser-card-s030:d0f09ee9-6684-44d7-92cb-56c85ea6cb35:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '67f7af57fab1f7eb2a5a0aef50451771bc4c91ced20da25a42196120d4273944|a5d9ac5e87f28d5c95f74a477df7ed2def7e9e91e0480f69d623c0bc1520b77b|a5d9ac5e87f28d5c95f74a477df7ed2def7e9e91e0480f69d623c0bc1520b77b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Next to the Roman road to Salacia, the Roman Villa of Tourega had a large bath with hot and cold water, separate for men and women, and amphorae almost all of which had held fish products."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the villa lay next to the Roman road to Salacia [S3]; it had a large bath [S5]; the bath had hot and cold water [S5]; the bath had separate facilities for men and women [S5]; amphorae were found at the villa [S6, S7]; almost all of the amphorae had held fish products [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Roman Villa of Tourega is a Roman villa (a farming estate with baths) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; The villa is in Portugal (Alentejo, Evora District) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; The villa lay next to the Roman road to Salacia [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; The villa had a large bath [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; The bath had hot and cold water [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; The bath had separate facilities for men and women [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; Amphorae were found at the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]; Almost all of the amphorae had held fish products [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Tourega]"}]'::jsonb),
    ('d1bbea1c-28b0-4441-a944-be72f9a40da1'::uuid, 'card_description', 'Founded some time in the centuries before 1000 BCE, Tres Zapotes emerged as a regional center early in the Middle Formative period, perhaps 900 - 800 BCE.', 'In 1939, on the Papaloapan River plain, Tres Zapotes gave up the bottom half of Stela C: carved from basalt, its back engraved with one of the few surviving examples of Epi-Olmec script.', 'teaser-card-s030:d1bbea1c-28b0-4441-a944-be72f9a40da1:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '6f8e5cb2d206fedbeed76e5e99ea0ae5c734f4a9b7d7a4be698756cc20ff3605|d79b94e1ef489addb388611cad3484165a6f5e44742f79e88e661db9f8a0b6cf|d79b94e1ef489addb388611cad3484165a6f5e44742f79e88e661db9f8a0b6cf', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In 1939, on the Papaloapan River plain, Tres Zapotes gave up the bottom half of Stela C: carved from basalt, its back engraved with one of the few surviving examples of Epi-Olmec script."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in 1939 the bottom half of Stela C was found at Tres Zapotes [S6]; Tres Zapotes is on the Papaloapan River plain [S1]; the stela is carved from basalt [S6]; its back is engraved with Epi-Olmec script [S7]; it is one of the few surviving examples of Epi-Olmec script [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tres Zapotes is an archaeological site (a Mesoamerican settlement and ceremonial centre) in Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]; Tres Zapotes lies on the Papaloapan River plain [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]; In 1939 an excavator discovered something at Tres Zapotes (the find dates to 1939) [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]; What was found was the bottom half of Stela C [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]; Stela C is carved from basalt [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]; The back of Stela C is engraved with script [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]; The script is Epi-Olmec and one of the few surviving examples [SUPPORTED: https://en.wikipedia.org/wiki/Tres_Zapotes]"}]'::jsonb),
    ('d1fb1d89-fc92-428f-9156-0b462f50569f'::uuid, 'card_description', 'A stone city from 900–1470 AD hidden in the Andean cloud forests, currently closed to visitors. Circular stone buildings are decorated with mosaic-like relief carvings.', 'In Andean cloud forest, Gran Pajatén crowns a hilltop with at least 26 circular stone structures on terraces and stairways, its main buildings set with slate mosaics of humans and birds.', 'teaser-card-s030:d1fb1d89-fc92-428f-9156-0b462f50569f:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '927e0d48a3bb900f1e49725d1b29a33ae0167377a86a847611dba7b08ddc3851|faafd910b60cafdd06ce581456c4470fe52ef2033dc235b6ed95d59ef8b265ef|faafd910b60cafdd06ce581456c4470fe52ef2033dc235b6ed95d59ef8b265ef', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Andean cloud forest, Gran Pajatén crowns a hilltop with at least 26 circular stone structures on terraces and stairways, its main buildings set with slate mosaics of humans and birds."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in Andean cloud forest [S1]; it sits on a hilltop [S3]; it has at least 26 circular stone structures [S3]; the structures stand on terraces and stairways [S3]; the main buildings are decorated with slate mosaics [S5]; the mosaics show humans [S5]; the mosaics show birds [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Gran Pajaten is an archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; It lies in Andean cloud forest [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; It sits on (crowns) a hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; It has at least 26 structures [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; The structures are circular and of stone [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; The structures stand on terraces and stairways [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; Its main (principal) buildings are decorated with slate mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]; The mosaics show humans and birds [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n]"}]'::jsonb),
    ('d2db72cb-3a9d-429f-98ad-e56925fcdc43'::uuid, 'card_description', 'A Neolithic chambered tomb from 3300 BC with an unusual multi-chambered design. The cairn contains both cist burials and entrance graves in one structure.', 'On a cliff top near St Just, Ballowall Barrow, also known as Carn Gluze Barrow, is 72 feet in diameter: a central domed structure holding cists and a pit beneath, ringed by an outer cairn.', 'teaser-card-s030:d2db72cb-3a9d-429f-98ad-e56925fcdc43:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8e3fd6df9a7ae262747c8e3a7f647518feb3104ac00d52a6dbf07b939e5041fa|a40e9632290bb23d1bc275e0481b65f6960709559ed163a6ce29535dbebd1bb6|a40e9632290bb23d1bc275e0481b65f6960709559ed163a6ce29535dbebd1bb6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a cliff top near St Just, Ballowall Barrow, also known as Carn Gluze Barrow, is 72 feet in diameter: a central domed structure holding cists and a pit beneath, ringed by an outer cairn."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "on a cliff top near St Just [S2]; also known as Carn Gluze Barrow [S3]; 72 feet in diameter [S5]; a central domed structure holding cists and a pit beneath [S6]; ringed by an outer cairn [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ballowall Barrow is a prehistoric funerary cairn (chambered tomb) on a cliff top near St Just in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Ballowall_Barrow]; Ballowall Barrow is a prehistoric funerary cairn [SUPPORTED: https://en.wikipedia.org/wiki/Ballowall_Barrow]; It is also known as Carn Gluze Barrow [SUPPORTED: https://en.wikipedia.org/wiki/Ballowall_Barrow]; The barrow is 72 feet in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Ballowall_Barrow]; It has a central domed structure containing cists with a pit beneath [SUPPORTED: https://en.wikipedia.org/wiki/Ballowall_Barrow]; The central structure is surrounded by an outer cairn [SUPPORTED: https://en.wikipedia.org/wiki/Ballowall_Barrow]"}]'::jsonb),
    ('d34647f5-e2ba-48e4-a5f1-12eec767b7ed'::uuid, 'card_description', 'A grand piano-shaped boulder on Ilkley Moor bearing sparse cup marks. Near the Swastika Stone, its purpose has never been agreed upon by archaeologists who have studied it for generations.', 'Like the lid of a grand piano, the Nebstone lies near the Swastika Stone on Ilkley Moor, with evidence of cup and ring marks, yet relatively few possible cup marks for so prominent a rock.', 'teaser-card-s030:d34647f5-e2ba-48e4-a5f1-12eec767b7ed:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7100f004adb33ace1910aa31e9cb71eb50ca3cf8420b8f9bda9fe1d2bef09c7e|c201b3476f9cab1ef7822d5af055a5ddc2a2911cff868f161ad4a421937c6132|c201b3476f9cab1ef7822d5af055a5ddc2a2911cff868f161ad4a421937c6132', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Like the lid of a grand piano, the Nebstone lies near the Swastika Stone on Ilkley Moor, with evidence of cup and ring marks, yet relatively few possible cup marks for so prominent a rock."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Nebstone looks like the lid of a grand piano [S2]; it lies near the Swastika Stone [S1]; it is on Ilkley Moor [S1]; it bears evidence of cup and ring marks [S3]; it has relatively few possible cup marks [S3]; it is a prominent rock [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Nebstone is a notable rock [SUPPORTED: https://en.wikipedia.org/wiki/Nebstone]; It lies near the Swastika Stone [SUPPORTED: https://en.wikipedia.org/wiki/Nebstone]; It is on Ilkley Moor [SUPPORTED: https://en.wikipedia.org/wiki/Nebstone]; It looks like the lid of a grand piano [SUPPORTED: https://en.wikipedia.org/wiki/Nebstone]; It bears evidence of cup and ring marks [SUPPORTED: https://en.wikipedia.org/wiki/Nebstone]; It has relatively few possible cup marks for so prominent a rock [SUPPORTED: https://en.wikipedia.org/wiki/Nebstone]"}]'::jsonb),
    ('d37895cc-6801-418e-a4b2-29b7001566ef'::uuid, 'card_description', 'Built under Hadrian (117–138 AD) near his birthplace of Italica, this amphitheatre seated roughly 25,000 spectators — a footprint rivalled by few in the empire — 300 m from the city''s north gate.', 'Beneath the old wooden floor of the Roman Amphitheatre of Italica lay a service pit for gladiatorial shows and fights against wild beasts. Built under Hadrian, it held 25,000 spectators.', 'teaser-card-s030:d37895cc-6801-418e-a4b2-29b7001566ef:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '90b7a805c36b7d3bde0f09c39e97dc86c1114804523e279e7d909d270adb72da|955dc49c18cff55d79567af6de595a13802e8020e0b575b2e6ab7d7b0774c31b|955dc49c18cff55d79567af6de595a13802e8020e0b575b2e6ab7d7b0774c31b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beneath the old wooden floor of the Roman Amphitheatre of Italica lay a service pit for gladiatorial shows and fights against wild beasts. Built under Hadrian, it held 25,000 spectators."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "beneath the old wooden floor of the amphitheatre lay a service pit [S6]; the pit served gladiatorial shows and fights against wild beasts [S6]; the amphitheatre was built under Hadrian [S2]; the amphitheatre held 25,000 spectators [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Roman Amphitheatre of Italica is a Roman amphitheatre in Italica (Santiponce, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_amphitheatre_of_Italica]; Beneath the old wooden floor there was a service pit [SUPPORTED: https://en.wikipedia.org/wiki/Roman_amphitheatre_of_Italica]; The service pit served gladiatorial shows and fights against wild beasts [SUPPORTED: https://en.wikipedia.org/wiki/Roman_amphitheatre_of_Italica]; It was built under Hadrian [SUPPORTED: https://en.wikipedia.org/wiki/Roman_amphitheatre_of_Italica]; It held 25,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Roman_amphitheatre_of_Italica]"}]'::jsonb),
    ('d515d518-5298-42f0-8da8-5f484e8bcdee'::uuid, 'card_description', 'Ruins of the Lycian city Idebessos, with a necropolis, Greek theatre, baths, and two early Christian churches. Founded around 168 BC.', 'At the foot of the Bey Mountains, 1050 m up, lie the ruins of İdebessos. Save for one controversially attributed coin, nothing shows this Lycian city existed before the Hellenistic period.', 'teaser-card-s030:d515d518-5298-42f0-8da8-5f484e8bcdee:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '2517ae2daf099923b873f8fcaa418ffcaf50f0709029b283c4b0e1973a70e451|86a0fd57fe4ca1161467a9ccdeee4014d8c8437231321f8613a6e613e6eb4f3e|86a0fd57fe4ca1161467a9ccdeee4014d8c8437231321f8613a6e613e6eb4f3e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the foot of the Bey Mountains, 1050 m up, lie the ruins of İdebessos. Save for one controversially attributed coin, nothing shows this Lycian city existed before the Hellenistic period."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the city lies at the foot of the Bey Mountains [S2]; it lies at an altitude of 1050 m [S4]; its ruins lie there [S3]; it was a Lycian city [S1]; apart from one controversially attributed coin, there is no evidence of the city''s existence before the Hellenistic period [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "İdebessos is an ancient Lycian city, whose ruins lie at the foot of the Bey Mountains (central claim: a city/settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Idebessos]; The ruins of the city survive today (near the village of Kozağacı, Kumluca district, Antalya Province, Türkiye) [SUPPORTED: https://en.wikipedia.org/wiki/Idebessos]; The city lies at an altitude of 1050 m [SUPPORTED: https://en.wikipedia.org/wiki/Idebessos]; One coin has been controversially attributed to the city (a coin from the Classical period) [SUPPORTED: https://en.wikipedia.org/wiki/Idebessos]; Apart from that coin, nothing shows the city existed before the Hellenistic period [SUPPORTED: https://en.wikipedia.org/wiki/Idebessos]"}]'::jsonb),
    ('d70dd131-fac7-4c7e-b367-95c2ac945339'::uuid, 'card_description', 'Excavation of the tombs at the Valley of the Queens was pioneered by Ernesto Schiaparelli and Francesco Ballerini in the early 1900s.', NULL, 'teaser-card-s030:d70dd131-fac7-4c7e-b367-95c2ac945339:card_description', 'teaser-card-s030 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||0a75ddfe18ef6cf846e40b5f21c294405089a5271fb002aa4c25497565c0c8a1', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: Ta-Set-Neferu means ''the Place of Beauty'' (stated as the meaning, without the alternative ''Place of the Royal Children''); S2 gives Ta-Set-Neferu a double meaning, ''The Place of Beauty'' and/or ''the Place of the Royal Children''; the card presents only ''the Place of Beauty'' as the name''s meaning and drops the and/or, which sharpens the description''s hedge. Give both meanings as S2 does, or drop the translation.; The web check could not prove: The Valley of the Queens is a burial site (in Egypt) (central claim: a burial site); The web check could not prove: The Valley of the Queens is a burial site in Egypt for queens, princes and princesses"}]'::jsonb),
    ('d760f193-0c0a-46fe-9af2-517846bf9171'::uuid, 'card_description', NULL, 'Roman aqueducts and leats, the longest about 7 miles, carried water to the Dolaucothi Gold Mines in the Cothi valley, where gold may have been washed from river gravels in the Bronze Age.', 'teaser-card-s030:d760f193-0c0a-46fe-9af2-517846bf9171:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '3b2a2dbe593856fc715529e559414ed296252559b571deda4e751fc7d5f7cc82|c045e9ff674d694cd38e83badc235222861e993e7a46fc93c44ad36dfaa1b585|c045e9ff674d694cd38e83badc235222861e993e7a46fc93c44ad36dfaa1b585', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Roman aqueducts and leats, the longest about 7 miles, carried water to the Dolaucothi Gold Mines in the Cothi valley, where gold may have been washed from river gravels in the Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Romans used water carried by aqueducts and leats at the mines [S5]; the longest of them is about 7 miles [S5]; the Dolaucothi Gold Mines lie in the Cothi valley [S1]; gold extraction there may have started in the Bronze Age, possibly by washing the river''s gold-bearing gravels [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Dolaucothi Gold Mines are ancient Roman gold mines (surface and underground) in Wales (central claim: a mine site) [SUPPORTED: https://en.wikipedia.org/wiki/Dolaucothi_Gold_Mines]; The mines lie in the Cothi valley [SUPPORTED: https://en.wikipedia.org/wiki/Dolaucothi_Gold_Mines]; The Romans carried water to the mines by aqueducts and leats [SUPPORTED: https://en.wikipedia.org/wiki/Dolaucothi_Gold_Mines]; The longest aqueduct or leat is about 7 miles long [SUPPORTED: https://en.wikipedia.org/wiki/Dolaucothi_Gold_Mines]; Gold may have been washed from river gravels in the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Dolaucothi_Gold_Mines]"}]'::jsonb),
    ('d7c688fd-ca27-4a8b-91fd-affbcc948eee'::uuid, 'card_description', 'A 75 m wide Bronze Age double burial—uniquely grand for the Nordic world. Its cist stones bear petroglyphs of processions and ships.', 'Near Kivik, the King''s Grave rises as a stone cairn about 75 metres across. Within, eight slabs of its cist bear carvings of ships, horses, birds, axes and figures playing lurs.', 'teaser-card-s030:d7c688fd-ca27-4a8b-91fd-affbcc948eee:card_description', 'teaser-card-s030 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '51635de1354c185edb000421ff13284e53bc1ff8c256743531bc0c5aad8aa387|b2c24f22a422b4bfa4270b308f5517402cd1a2a48789db3e38640c50e1900fff|b2c24f22a422b4bfa4270b308f5517402cd1a2a48789db3e38640c50e1900fff', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Kivik, the King''s Grave rises as a stone cairn about 75 metres across. Within, eight slabs of its cist bear carvings of ships, horses, birds, axes and figures playing lurs."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the King''s Grave lies near Kivik [S1]; it is a stone cairn [S2]; the cairn measures about 75 metres across [S3]; a cist lies within the cairn [S4]; eight slabs of the cist are carved [S5]; the carvings show ships, horses, birds, axes and figures playing lurs [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The King''s Grave is a stone cairn (a burial monument) (central claim: a burial cairn) [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]; It lies near Kivik, Sweden [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]; The cairn is about 75 metres across [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]; The cairn contains a cist (a stone-built burial chamber) [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]; Eight slabs of the cist bear carvings [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]; The carvings depict ships, horses, birds and axes [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]; The carvings depict figures playing lurs [SUPPORTED: https://en.wikipedia.org/wiki/The_King%27s_Grave]"}]'::jsonb),
    ('d9413d19-05a0-4bac-bed2-da8462ca46b6'::uuid, 'card_description', 'Vrokastro was an ancient Minoan civilization settlement in the Lasithi regional unit of eastern Crete. Vrokastro bridges the end of the Bronze Age and the beginning of the early Iron Age.', 'On a hill overlooking the Gulf of Mirabello, 300 m up, the Minoan mountain citadel of Vrokastro bridges the end of the Bronze Age and the beginning of the early Iron Age in eastern Crete.', 'teaser-card-s030:d9413d19-05a0-4bac-bed2-da8462ca46b6:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'a64d31da1fbda4151740eb9595b56b2f4423851a943a2cad726947747217f7f6|868e16f0f3f32ec0d927d2043f6ceb78c061be4275f23bfa00e89fd6c83749f5|868e16f0f3f32ec0d927d2043f6ceb78c061be4275f23bfa00e89fd6c83749f5', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a hill overlooking the Gulf of Mirabello, 300 m up, the Minoan mountain citadel of Vrokastro bridges the end of the Bronze Age and the beginning of the early Iron Age in eastern Crete."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on a hill [S3]; it overlooks the Gulf of Mirabello [S2]; the settlement lies at an elevation of 300 m [S6]; it is a Minoan mountain citadel [S1, S3]; it bridges the end of the Bronze Age and the beginning of the early Iron Age [S4]; it lies in eastern Crete [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Vrokastro is a Minoan mountain citadel (settlement) (central claim: a citadel/settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]; The site was a mountain citadel on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]; It is in eastern Crete [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]; It overlooks the Gulf of Mirabello [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]; The elevation of the settlement is 300 m [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]; Vrokastro bridges the end of the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]; Vrokastro bridges the beginning of the early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Vrokastro]"}]'::jsonb),
    ('da4f66f6-683b-4655-a694-279361b05529'::uuid, 'card_description', 'A Roman road that ran 160 km from the Humber Estuary to the River Tyne. Its exact course is still debated, though evidence exists on parts of the proposed route.', 'Its Roman name is unknown, its exact course still in doubt: Cade''s Road, proposed in 1785, ran from a ferry and Roman fort at Brough on the Humber past the fort of Concangis.', 'teaser-card-s030:da4f66f6-683b-4655-a694-279361b05529:card_description', 'teaser-card-s030 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '38c221b2abb675eb0b45d85d0a90d017dbe187fcee0c7cc84aee00d3e2d7cb94|e6b5104dbd9d913e21c6eb31c5ae9a943f76a464a24950c54d08e76280e368ad|e6b5104dbd9d913e21c6eb31c5ae9a943f76a464a24950c54d08e76280e368ad', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its Roman name is unknown, its exact course still in doubt: Cade''s Road, proposed in 1785, ran from a ferry and Roman fort at Brough on the Humber past the fort of Concangis."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the road''s Roman name is unknown [S3]; its exact course is still in doubt [S4]; the road was proposed in 1785 [S2]; it began at Brough on the Humber, where there was a ferry and a Roman fort [S5]; it ran past the fort of Concangis [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cade''s Road is a Roman road (in north-east England) [SUPPORTED: https://en.wikipedia.org/wiki/Cade%27s_Road]; Its Roman name is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Cade%27s_Road]; Its exact course is still in doubt [SUPPORTED: https://en.wikipedia.org/wiki/Cade%27s_Road]; The road was proposed in 1785 [SUPPORTED: https://en.wikipedia.org/wiki/Cade%27s_Road]; It ran from Brough on the Humber, where there was a ferry and a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Cade%27s_Road]; The road ran past the Roman fort of Concangis [SUPPORTED: https://en.wikipedia.org/wiki/Cade%27s_Road]"}]'::jsonb),
    ('dae9bc10-f90d-45d4-9ab6-1408912b461e'::uuid, 'card_description', 'The Wroxeter Stone is the name given to a circa 460–75 AD inscribed stone unearthed in 1967 at Wroxeter.', 'Unearthed in 1967 where the Roman city of Viroconium Cornoviorum once stood, the Wroxeter Stone names Cunorīx, the hound-king, son of Maqqos Colinī, a name meaning son of holly.', 'teaser-card-s030:dae9bc10-f90d-45d4-9ab6-1408912b461e:card_description', 'teaser-card-s030 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '49896cd87f94361cc66a27ea6c4e961277bde117b39cdc2a1bf8c7f8f69e6c37|4a8ecbe45ddcfa2978cd0b73cf7a184d971bdc2181de8005a099a534e13da7f8|4a8ecbe45ddcfa2978cd0b73cf7a184d971bdc2181de8005a099a534e13da7f8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Unearthed in 1967 where the Roman city of Viroconium Cornoviorum once stood, the Wroxeter Stone names Cunorīx, the hound-king, son of Maqqos Colinī, a name meaning son of holly."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the stone was unearthed in 1967 [S1]; it was found where the Roman city of Viroconium Cornoviorum once stood (Wroxeter) [S1]; the stone names Cunorīx [S2]; Cunorīx literally means ''hound-king'' [S3]; Cunorīx is the son of Maqqos Colinī [S2]; Maqqos Colinī literally means ''son of holly'' [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Wroxeter Stone is an inscribed stone, found at Wroxeter, England [SUPPORTED: https://en.wikipedia.org/wiki/Wroxeter_Stone]; The stone was unearthed in 1967 [SUPPORTED: https://en.wikipedia.org/wiki/Wroxeter_Stone]; Wroxeter was earlier the Roman city of Viroconium Cornoviorum [SUPPORTED: https://en.wikipedia.org/wiki/Wroxeter_Stone]; The stone names Cunorix (the inscription reads CVNORIX) [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Wroxeter_Stone]; Cunorix is the son of Maqqos Colini (the inscription names the father Maqqos Colini) [SUPPORTED: https://en.wikipedia.org/wiki/Wroxeter_Stone]; Cunorix means hound-king [SUPPORTED: https://en.wikipedia.org/wiki/Wroxeter_Stone]; The name Maqqos Colini means son of holly [SUPPORTED: https://en.wikipedia.org/wiki/Wroxeter_Stone]"}]'::jsonb),
    ('dc51894b-cc2c-4d5d-81ae-955eb846326f'::uuid, 'card_description', 'Heraclea Sintica was founded sometime between 356 and 339 BC by Philip II of Macedon with Macedonian settlers from Heraclea in Mygdonia.', 'Philip II of Macedon founded Heraclea Sintica near Rupite with Macedonian settlers. Thracian names are conspicuously absent from its inscriptions, as if the Sintoi were driven out.', 'teaser-card-s030:dc51894b-cc2c-4d5d-81ae-955eb846326f:card_description', 'teaser-card-s030 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f0ab66942e8e147a300c1beae98c841cd2eabcbb4015314717507b1d7f114f02|38d292aa6af3feab4042bdf1c8f6408157e7142d60133dc5edb7c091e8f17fb0|38d292aa6af3feab4042bdf1c8f6408157e7142d60133dc5edb7c091e8f17fb0', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Philip II of Macedon founded Heraclea Sintica near Rupite with Macedonian settlers. Thracian names are conspicuously absent from its inscriptions, as if the Sintoi were driven out."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Philip II of Macedon founded Heraclea Sintica [S2]; it was founded with Macedonian settlers [S2]; it lies near Rupite [S1]; there is a conspicuous absence of Thracian names in its inscriptions [S5]; this suggests the Sintoi had been driven out (hedged) [S4, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Heraclea Sintica was an ancient city (settlement) near Rupite, in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Heraclea_Sintica]; Philip II of Macedon founded Heraclea Sintica [SUPPORTED: https://en.wikipedia.org/wiki/Heraclea_Sintica]; It was founded with Macedonian settlers [SUPPORTED: https://en.wikipedia.org/wiki/Heraclea_Sintica]; Thracian names are conspicuously absent from the inscriptions of Heraclea [SUPPORTED: https://en.wikipedia.org/wiki/Heraclea_Sintica]; The absence suggests the Sintoi were driven out [SUPPORTED: https://en.wikipedia.org/wiki/Heraclea_Sintica]"}]'::jsonb),
    ('dd6ec46e-813f-458a-a881-a5673ea8b839'::uuid, 'card_description', 'A cave complex next to mysterious prehistoric cart ruts carved into bedrock. Families reportedly lived as troglodytes in these caves until 1835.', 'Cut into the rock at Siggiewi, Għar il-Kbir spreads eight caves across two levels beside a set of cart ruts, and families of troglodytes are commonly believed to have lived here until 1835.', 'teaser-card-s030:dd6ec46e-813f-458a-a881-a5673ea8b839:card_description', 'teaser-card-s030 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '1c50debd284353b76be4440c0b83672946e88abf67dbd026581a2a030ee7477a|4f046f91a4f16755233124e50135eb9d164e3296d16affa233e28e3904f41d03|4f046f91a4f16755233124e50135eb9d164e3296d16affa233e28e3904f41d03', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cut into the rock at Siggiewi, Għar il-Kbir spreads eight caves across two levels beside a set of cart ruts, and families of troglodytes are commonly believed to have lived here until 1835."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is cut into the rock (rock-cut structures) [S1]; it is at Siggiewi [S1]; it has eight caves across two levels [S4]; cart ruts lie beside it [S2]; families of troglodytes are commonly believed to have lived there until 1835 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Għar il-Kbir is a complex of rock-cut structures (caves cut into the rock) at Siġġiewi, Malta [SUPPORTED: https://en.wikipedia.org/wiki/Għar_il-Kbir]; The cave system has eight caves [SUPPORTED: https://en.wikipedia.org/wiki/Għar_il-Kbir]; The eight caves are spread across two levels [SUPPORTED: https://en.wikipedia.org/wiki/Għar_il-Kbir]; Several cart ruts are located next to the caves [SUPPORTED: https://en.wikipedia.org/wiki/Għar_il-Kbir]; It is commonly believed that families of troglodytes lived in the caves [SUPPORTED: https://en.wikipedia.org/wiki/Għar_il-Kbir]; The troglodyte families are believed to have lived there until 1835 [SUPPORTED: https://en.wikipedia.org/wiki/Għar_il-Kbir]"}]'::jsonb),
    ('dda2cc28-1dc6-4ba9-80c2-1f933e4a8447'::uuid, 'card_description', 'Andautonia was a Roman settlement located on the southern bank of the river Sava, located in the modern-day village of Šćitarjevo, southeast of the city of Zagreb.', 'On the southern bank of the Sava lay Roman Andautonia, believed destroyed in the Great Migration. A tablet found in 1768 bears a dedication to Herennia Etruscilla, wife of Emperor Decius.', 'teaser-card-s030:dda2cc28-1dc6-4ba9-80c2-1f933e4a8447:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '0fda6c14b736ccb49d0300d19b9f6d0fb52fa2aded8921514f9a324854bc264b|f3e79b722e35f9f75088b941fce4c3ac502751b5bed472f0b9ec48423cae69c8|f3e79b722e35f9f75088b941fce4c3ac502751b5bed472f0b9ec48423cae69c8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the southern bank of the Sava lay Roman Andautonia, believed destroyed in the Great Migration. A tablet found in 1768 bears a dedication to Herennia Etruscilla, wife of Emperor Decius."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Andautonia lay on the southern bank of the Sava [S1]; it was a Roman settlement [S1]; it is believed to have been destroyed in the Great Migration (hedged) [S3]; a tablet found in 1768 carries an inscription [S4, S7]; the inscription is a dedication to Herennia Etruscilla [S7]; Herennia Etruscilla was the wife of Emperor Decius [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Andautonia was a Roman settlement [SUPPORTED: https://en.wikipedia.org/wiki/Andautonia]; Andautonia lay on the southern bank of the Sava [SUPPORTED: https://en.wikipedia.org/wiki/Andautonia]; It is believed to have been destroyed during the Great Migration [SUPPORTED: https://en.wikipedia.org/wiki/Andautonia]; A tablet (inscription) was found in 1768 [SUPPORTED: https://en.wikipedia.org/wiki/Andautonia]; The tablet found in 1768 bears a dedication to Herennia Etruscilla [SUPPORTED: https://en.wikipedia.org/wiki/Andautonia]; Herennia Etruscilla was the wife of Emperor Decius [SUPPORTED: https://en.wikipedia.org/wiki/Andautonia]"}]'::jsonb),
    ('ddd829b1-fdad-4487-a284-35bae4539928'::uuid, 'card_description', 'A Castro culture settlement with advanced stone architecture and an "urban" layout rare for Iron Age Iberia. Most ruins date to a massive 1st-century BC expansion.', 'On the small promontory of Monte de São Romão, four lines of walls ring the roughly oval Citânia de Briteiros, an Iron Age hill fort of the Castro culture near Guimarães.', 'teaser-card-s030:ddd829b1-fdad-4487-a284-35bae4539928:card_description', 'teaser-card-s030 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '8bcd66868fa81efe479afe51b2f95d9f31deb06883da5a18d2b210d521f4023c|54f92d831e05725acaf5081eac69f4a4e20ed764400a3af7627d753b68ebee5b|54f92d831e05725acaf5081eac69f4a4e20ed764400a3af7627d753b68ebee5b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the small promontory of Monte de São Romão, four lines of walls ring the roughly oval Citânia de Briteiros, an Iron Age hill fort of the Castro culture near Guimarães."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site stands on the small promontory of Monte de São Romão [S4]; four lines of walls [S5]; the plan is roughly (approximately) oval [S5]; it is an Iron Age hill fort [S2, S3]; it belongs to the Castro culture [S1]; it lies near Guimarães [S1, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Citânia de Briteiros is an Iron Age hill fort (the central claim: a hill fort / fortified settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Briteiros]; It belongs to the Castro culture [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Briteiros]; It lies near Guimarães [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Briteiros]; It stands on the small promontory of Monte de São Romão [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Briteiros]; Four lines of walls ring the site [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Briteiros]; The site is roughly oval [SUPPORTED: https://en.wikipedia.org/wiki/Cit%C3%A2nia_de_Briteiros]"}]'::jsonb),
    ('deea88d4-dfe2-42b2-bee6-a76f34f7d00b'::uuid, 'card_description', 'Compact at 108 by 88 metres in Grinton, this settlement carries a name derived from an old term for a fortification held to be impregnable. Its Iron Age date is inferred from its earthwork form.', 'An avenue, a unique feature, leads to the entrance of Maiden Castle at Grinton, a pear-shaped settlement of 108 by 88 m that probably dates from the Iron Age, now a scheduled monument.', 'teaser-card-s030:deea88d4-dfe2-42b2-bee6-a76f34f7d00b:card_description', 'teaser-card-s030 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '2cb2e1d671763ec2bde2d37525417ad6168e9e414ef5fc9183a9c4b5211bb7af|524433391eecdef943a276ecdb08eb51fd617a2a23b9ac52f453554a2ae33016|524433391eecdef943a276ecdb08eb51fd617a2a23b9ac52f453554a2ae33016', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "An avenue, a unique feature, leads to the entrance of Maiden Castle at Grinton, a pear-shaped settlement of 108 by 88 m that probably dates from the Iron Age, now a scheduled monument."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "an avenue leads to the entrance of the settlement [S4]; the avenue is a unique feature [S4]; the site is at Grinton [S1]; the settlement is pear-shaped [S3]; it measures 108 by 88 m [S3]; it probably dates from the Iron Age [S1]; it is a scheduled monument [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Maiden Castle at Grinton, North Yorkshire is a settlement (the central claim: a settlement, not a fort or tomb) [SUPPORTED: https://en.wikipedia.org