    ('df056ae9-c7c1-4a2d-93f9-76e9d6bd0f93'::uuid, 'card_description', 'Greco-Roman theatre seating 13,000 at ancient Halicarnassus -- city of the Mausoleum, a Wonder of the Ancient World. The theatre dates to the 4th century BC.', 'Its construction attributed to the reign of the Carian Satrap Mausolos, the Bodrum Antique Theatre originally seated 10,000 to 13,000 people around an orchestra 18 meters across.', 'teaser-card-s030:df056ae9-c7c1-4a2d-93f9-76e9d6bd0f93:card_description', 'teaser-card-s030 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '0fb7628f6c74b2eee93cb06fe034bab7507c86040e192f9ce29548e5bf263315|f26cf448dc42ee184c769c86404da89b2b6f6f7bdab5ad409db13d289d27a333|f26cf448dc42ee184c769c86404da89b2b6f6f7bdab5ad409db13d289d27a333', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its construction attributed to the reign of the Carian Satrap Mausolos, the Bodrum Antique Theatre originally seated 10,000 to 13,000 people around an orchestra 18 meters across."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "construction is attributed to the reign of the Carian Satrap Mausolos [S3]; the theatre originally seated 10,000 to 13,000 people [S4]; the orchestra is 18 meters across [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Bodrum Antique Theatre is an ancient Greco-Roman theatre in Bodrum (the central claim: a theatre) [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_at_Halicarnassus]; Its construction is attributed to the reign of the Carian Satrap Mausolos [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_at_Halicarnassus]; It originally seated 10,000 to 13,000 people [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_at_Halicarnassus]; The upper capacity figure of 13,000 seats is given by the Bodrum municipality [SUPPORTED: https://www.bodrum.bel.tr/page.php?id=23%2Fantik_tiyatro]; The lower capacity figure of 10,000 is given as the original capacity [SUPPORTED: https://www.whitman.edu/theatre/theatretour/halicarnassus/halicarnassus.htm]; The orchestra is 18 meters across [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_at_Halicarnassus]; The orchestra diameter is 18 meters (second source) [SUPPORTED: https://www.whitman.edu/theatre/theatretour/halicarnassus/halicarnassus.htm]"}]'::jsonb),
    ('df4987a2-4247-4be4-8d1c-89e3e6f816fe'::uuid, 'card_description', 'Iron Age hill fort crowning Long Mountain at 408 metres, possibly crossed by a Roman road linking Wroxeter to Forden Gaer. The summit lies within one country while the mountain straddles two.', NULL, 'teaser-card-s030:df4987a2-4247-4be4-8d1c-89e3e6f816fe:card_description', 'teaser-card-s030 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||f1dce679d1daef0cf8d6082ab43183b2e206f3d3741c3a20ab8b7133065b135e', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check could not prove: Beacon Ring is the hillfort crowning Long Mountain, Powys (the central claim: a hilltop hillfort site); The web check could not prove: Beacon Ring is a hillfort at the southern end of Long Mountain, in Wales; The web check could not prove: Long Mountain lies east of Welshpool; The web check could not prove: The summit of Long Mountain is 408 metres high; The web check could not prove: Beacon Ring is covered by a tree plantation; The web check could not prove: Long Mountain lies east of Welshpool and straddles the boundary between Powys and Shropshire; The web check could not prove: The summit at 408 metres is at Beacon Ring, within Wales; The web check could not prove: Beacon Ring is famous for the EIIR monogram of the tree plantation covering the site"}]'::jsonb),
    ('e0bdbec4-268a-4b70-bb73-3e0a74351b9d'::uuid, 'card_description', 'A Roman frontier fort on the Rhine, fortified in 47 AD under Emperor Claudius. The modern city that grew on its ruins still carries a version of its Latin name.', 'In the center of Utrecht lie the remains of Traiectum, a Roman frontier fort burned in the revolt of the Batavi and rebuilt four times, each time raised up by adding fill.', 'teaser-card-s030:e0bdbec4-268a-4b70-bb73-3e0a74351b9d:card_description', 'teaser-card-s030 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '87cc8ac86a16849d5247c4e696ec1f4ee1c6d73ae574f4406072f3653d958081|4ec2e6455e91ef8a29c662df1c651de697fa4eefd760bde76557fe64285a6102|4ec2e6455e91ef8a29c662df1c651de697fa4eefd760bde76557fe64285a6102', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the center of Utrecht lie the remains of Traiectum, a Roman frontier fort burned in the revolt of the Batavi and rebuilt four times, each time raised up by adding fill."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the remains of Traiectum lie in the center of Utrecht [S2]; Traiectum was a Roman fort [S1]; the fort was on the frontier of the Roman Empire [S1]; the fort was burned during the revolt of the Batavi [S4]; the fort was rebuilt four times [S5]; each time it was raised up by adding fill [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Traiectum is a Roman fort (the central claim: a Roman fort) [SUPPORTED: https://en.wikipedia.org/wiki/Traiectum_(Utrecht)]; The fort stood on the frontier of the Roman Empire [SUPPORTED: https://en.wikipedia.org/wiki/Traiectum_(Utrecht)]; Its remains lie in the center of Utrecht [SUPPORTED: https://en.wikipedia.org/wiki/Traiectum_(Utrecht)]; The fort was destroyed in the revolt of the Batavi (Batavian Revolt) [SUPPORTED: https://www.livius.org/articles/place/traiectum-utrecht/]; The fort was burned in the revolt of the Batavi [SUPPORTED: https://en.wikipedia.org/wiki/Traiectum_(Utrecht)]; The fort was rebuilt four times [SUPPORTED: https://en.wikipedia.org/wiki/Traiectum_(Utrecht)]; Each rebuilding was raised up by adding fill [SUPPORTED: https://en.wikipedia.org/wiki/Traiectum_(Utrecht)]"}]'::jsonb),
    ('e14380ae-7474-4960-8aa2-0c4b85569cae'::uuid, 'card_description', 'The Mên-an-Tol is thought to date to either the late Neolithic or early Bronze Age.', 'Three upright granite stones stand in Cornwall: the Mên-an-Tol, its roughly octagonal stone holed by a circle 0.5 m in diameter, thought to date to the late Neolithic or early Bronze Age.', 'teaser-card-s030:e14380ae-7474-4960-8aa2-0c4b85569cae:card_description', 'teaser-card-s030 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'de9a120dac412bff6b3f5ef1070c54a5f31f8a483039a203970856c1b15335d3|4d5bcd9367e08e857e4b7cce481237b6e958bde4f166d4f0ecf7c6dd5927175b|4d5bcd9367e08e857e4b7cce481237b6e958bde4f166d4f0ecf7c6dd5927175b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Three upright granite stones stand in Cornwall: the Mên-an-Tol, its roughly octagonal stone holed by a circle 0.5 m in diameter, thought to date to the late Neolithic or early Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "three upright granite stones stand in Cornwall [S1, S2]; the monument is the Mên-an-Tol [S1]; its holed stone is roughly octagonal in outline [S5]; the hole is circular and 0.5 m in diameter [S6]; the Mên-an-Tol is thought to date to the late Neolithic or early Bronze Age (hedge kept) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Mên-an-Tol is a small formation of standing stones in Cornwall (a megalithic stone monument) [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%AAn-an-Tol]; The Mên-an-Tol consists of three upright granite stones [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%AAn-an-Tol]; The holed stone is roughly octagonal in outline [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%AAn-an-Tol]; The stone is holed by a circular hole 0.5 m in diameter [SUPPORTED, no proving quote: https://historicengland.org.uk/listing/the-list/list-entry/1004641]; The Mên-an-Tol is thought to date to the late Neolithic or early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/M%C3%AAn-an-Tol]"}]'::jsonb),
    ('e1548be0-b310-4afd-82dc-bce186b01410'::uuid, 'card_description', 'A Roman temple in Gloucestershire built over an earlier prehistoric shrine. Lead curse tablets recovered here spell out exactly what ordinary worshippers asked their gods to avenge.', 'Near Uley the Romans built a temple on an earlier prehistoric shrine. A water main laid in 1976 turned up lead curse tablets from the temple area, which often appear to relate to theft.', 'teaser-card-s030:e1548be0-b310-4afd-82dc-bce186b01410:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '5a08faff7e5cd31d7182ffae1c97fc50b12a8654fd22d5d8c2018c8768b53fbe|872d92ee847ff8654c6b57811f21edb13d7aaaf2d1b9246d0ff4727b4bba381f|872d92ee847ff8654c6b57811f21edb13d7aaaf2d1b9246d0ff4727b4bba381f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Uley the Romans built a temple on an earlier prehistoric shrine. A water main laid in 1976 turned up lead curse tablets from the temple area, which often appear to relate to theft."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Romans built a temple near Uley [S1]; the temple stood on the site of an earlier prehistoric shrine [S1]; a water main was laid there in 1976 [S2]; the laying of the water main was followed by the discovery of lead curse tablets from the temple area [S2]; the tablets often appear to relate to theft (hedge kept) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Romans built a temple near Uley (at West Hill) [SUPPORTED: https://en.wikipedia.org/wiki/Uley]; The Roman temple stood on the site of an earlier prehistoric shrine [SUPPORTED: https://en.wikipedia.org/wiki/Uley]; A water main was laid at West Hill, Uley in 1976 (and brought the temple site to light) [SUPPORTED: http://curses.csad.ox.ac.uk/sites/uley-home.shtml]; Lead curse tablets were found from the temple area [SUPPORTED: https://en.wikipedia.org/wiki/Uley]; The tablets often appear to relate to theft [SUPPORTED: https://en.wikipedia.org/wiki/Uley]"}]'::jsonb),
    ('e1ad1065-22ed-4345-8b7a-f02f779a7458'::uuid, 'card_description', 'Iron Age earthworks on the Isle of Wight — an apparently unfinished promontory fort. Construction stopped mid-project; whatever threat prompted it may have passed.', 'On the Isle of Wight, between Shorwell and Chillerton, earthworks run across a spur of Chillerton Down: the Five Barrows, about 84 metres long, 5 metres wide and up to 3 metres high.', 'teaser-card-s030:e1ad1065-22ed-4345-8b7a-f02f779a7458:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '3c57d8bd80663745bd76dadd0b2d0f3418a44c7fd6686ec4a3ec0aa1f903a9a3|e199b1dbf20581d6e386a921c3218abd171390eabf5acb7a3853d062c918d60c|e199b1dbf20581d6e386a921c3218abd171390eabf5acb7a3853d062c918d60c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Isle of Wight, between Shorwell and Chillerton, earthworks run across a spur of Chillerton Down: the Five Barrows, about 84 metres long, 5 metres wide and up to 3 metres high."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "on the Isle of Wight between Shorwell and Chillerton [S1]; earthworks run across a spur of the hill [S2]; the feature is called the Five Barrows [S3]; about 84 metres long [S4]; 5 metres wide [S4]; up to 3 metres high [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Chillerton Down is downland on the Isle of Wight between Shorwell and Chillerton, England [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]; Earthworks run across a spur of the hill, called the Five Barrows [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]; The feature is called the Five Barrows [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]; The earthwork is about 84 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]; The earthwork is about 5 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]; The earthwork is up to 3 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]; The rampart is about 84 metres long, 5 metres wide and up to 3 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Chillerton_Down]"}]'::jsonb),
    ('e1e4e79c-a9c4-4169-8fde-371c0df79061'::uuid, 'card_description', 'The Large Theatre was built into a natural hill in the second century BC and was one of the first permanent stone theatres in the Roman empire.', 'In the Theatre Area of Pompeii, a Large Theatre built into a hill in the second century BC seated roughly 5,000 spectators, one of the first permanent stone theatres in the Roman empire.', 'teaser-card-s030:e1e4e79c-a9c4-4169-8fde-371c0df79061:card_description', 'teaser-card-s030 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '0f7e83978548fd0ae34b103fba3c71903e7aa65200b02e1374158c841f5e658a|58c0bf2c881ea5914006fba369db2e079c96ee57d0f82290443b69a842405b29|58c0bf2c881ea5914006fba369db2e079c96ee57d0f82290443b69a842405b29', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Theatre Area of Pompeii, a Large Theatre built into a hill in the second century BC seated roughly 5,000 spectators, one of the first permanent stone theatres in the Roman empire."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Theatre Area of Pompeii contains a Large Theatre [S1, S2]; the Large Theatre was built into a hill [S4]; it was built in the second century BC [S4]; it seated roughly 5,000 spectators [S5]; it was one of the first permanent stone theatres in the Roman empire [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Theatre Area of Pompeii is a theatre complex in the city of Pompeii, with the Large Theatre as one of its main buildings [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_Area_of_Pompeii]; The Large Theatre was built in the second century BC [SUPPORTED: https://www.pompeii.org.uk/m.php/museum-large-theatre-pompeii-en-85-m.htm]; The Large Theatre was built into a hill (natural slope) [SUPPORTED: https://www.worldhistory.org/image/11296/the-large-theatre-of-pompeii/]; The Large Theatre seated roughly 5,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_Area_of_Pompeii]; The Large Theatre was one of the first permanent stone theatres in the Roman empire [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_Area_of_Pompeii]"}]'::jsonb),
    ('e212d748-501b-4c73-bdf7-7e96fbeabf35'::uuid, 'card_description', '15th-century Wancas-period site with circular stone buildings at 3,850 metres in Junín Region. The circular plan sets it apart from standard Inca rectangular construction on the surrounding slopes.', 'High in Peru''s Junín Region, at the foot of a mountain named Winchus, 3,850 metres up, Quri Winchus preserves remains of circular buildings in Canchayllo District, Jauja Province.', 'teaser-card-s030:e212d748-501b-4c73-bdf7-7e96fbeabf35:card_description', 'teaser-card-s030 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'bc273b680a843f697a2b32031b25dc62b46a75fab3371779f22c14402306f0ed|14838fbcdd82dddbf1c2e61b502f0a9cb0cb8bb92d0aa0fdcf0e93db5c5f7b4d|14838fbcdd82dddbf1c2e61b502f0a9cb0cb8bb92d0aa0fdcf0e93db5c5f7b4d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "High in Peru''s Junín Region, at the foot of a mountain named Winchus, 3,850 metres up, Quri Winchus preserves remains of circular buildings in Canchayllo District, Jauja Province."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in Peru''s Junín Region [S2]; at the foot of a mountain named Winchus [S4]; at 3,850 metres [S4]; remains of circular buildings [S1]; in Canchayllo District, Jauja Province [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Quri Winchus is an archaeological site with remains of circular buildings [SUPPORTED: https://en.wikipedia.org/wiki/Quri_Winchus]; The site is in Peru''s Junin Region [SUPPORTED: https://en.wikipedia.org/wiki/Quri_Winchus]; The site is in Jauja Province [SUPPORTED: https://en.wikipedia.org/wiki/Quri_Winchus]; The site is in Canchayllo District [SUPPORTED: https://en.wikipedia.org/wiki/Quri_Winchus]; It lies at a height of 3,850 metres [SUPPORTED: https://en.wikipedia.org/wiki/Quri_Winchus]; It lies at the foot of a mountain named Winchus [SUPPORTED: https://en.wikipedia.org/wiki/Quri_Winchus]"}]'::jsonb),
    ('e2574770-baac-4cba-a7c3-16e5b2650f8d'::uuid, 'card_description', 'A 4th-century BC sanctuary near Montealegre del Castillo with hundreds of votive stone sculptures, many depicting women in elaborate headdresses. Use continued into the Roman period.', 'At Cerro de los Santos, an Iberian sanctuary built in the 4th century BCE, about 300 votive sculptures accumulated, most depicting women; some later ones bear Latin letter inscriptions.', 'teaser-card-s030:e2574770-baac-4cba-a7c3-16e5b2650f8d:card_description', 'teaser-card-s030 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '536a54254fe1f71d14f869e8e8ba5c554c7cecfc31c6c43dfcab84fe0fd3a995|934fce8061d23206df34ba4acfe39cbe97059fa3a184dfe6942a0c31ad909493|934fce8061d23206df34ba4acfe39cbe97059fa3a184dfe6942a0c31ad909493', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Cerro de los Santos, an Iberian sanctuary built in the 4th century BCE, about 300 votive sculptures accumulated, most depicting women; some later ones bear Latin letter inscriptions."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cerro de los Santos is an Iberian sanctuary [S1]; it was built in the 4th century BCE [S1]; about 300 votive sculptures are known from the site [S2]; the sculptures accumulated over time [S6]; most of the sculptures depict women [S3]; some later sculptures bear Latin letter inscriptions [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cerro de los Santos is an Iberian religious sanctuary (the kind of place the text is about) [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]; The sanctuary is in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]; The sanctuary was built in the 4th century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]; About 300 votive sculptures were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]; The sculptures accumulated over time [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]; Most of the sculptures depict women [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]; Some later sculptures bear Latin letter inscriptions [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_de_los_Santos]"}]'::jsonb),
    ('e2f2dee4-9e70-41b8-a7f5-be7aa07ea807'::uuid, 'card_description', 'Funerary stele of 510 BC carved from Pentelic marble at 2.02 m tall, showing a warrior in full armour. Traces of polychrome paint survive—confirming ancient sculpture was vividly coloured.', 'Found near Marathon, the Stele of Aristion was carved around 510 BC by Aristokles from Pentelic marble and once painted with meanders and zig-zags; its base names the deceased: Aristion''s.', 'teaser-card-s030:e2f2dee4-9e70-41b8-a7f5-be7aa07ea807:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '2712e69de7f80e773c29fd5d3589af84b7369896d3c3377e3da7d8e5c3ef6aa0|4e45c85a463748085a2283ca001647eaa6e588554140f4172c9ff915ac9bb8f9|4e45c85a463748085a2283ca001647eaa6e588554140f4172c9ff915ac9bb8f9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found near Marathon, the Stele of Aristion was carved around 510 BC by Aristokles from Pentelic marble and once painted with meanders and zig-zags; its base names the deceased: Aristion''s."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the stele was found near Marathon [S3]; it dates from around 510 BC [S1, S4]; it was created by Aristokles [S2]; it is made of Pentelic marble [S2]; it was originally decorated with painted meanders and zig-zags [S7]; its base carries an inscription naming the deceased as Aristion''s [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Stele of Aristion is a funerary stele (the kind of object the text is about) [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; It was found near Marathon [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; It was carved around 510 BC [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; It was carved by Aristokles [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; It is made of Pentelic marble [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; It was once painted with meanders [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; It was once painted with zig-zags [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; Its base carries an inscription naming the deceased [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]; The base inscription gives the name of the deceased as Aristion''s (genitive) [SUPPORTED: https://en.wikipedia.org/wiki/Stele_of_Aristion]"}]'::jsonb),
    ('e2fab8b2-fe0a-4691-9556-3fc8d71ed312'::uuid, 'card_description', 'Lismore broch set on a rocky eastern height, 4 km north of Achnacroish. Clear-day views reach Ben Nevis to the north, Ben Cruachan to the east, and the Paps of Jura to the south.', 'On a rocky height on the east coast of Lismore stands Tirefour Castle, an Iron Age broch whose dry stone wall survives up to 4.9 metres. Its finds include an enamel brooch and a Norse pin.', 'teaser-card-s030:e2fab8b2-fe0a-4691-9556-3fc8d71ed312:card_description', 'teaser-card-s030 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'acb2dbbb0ac19b0f7556a90978f1e353a313bb9a8ab68cdb7d5bc40091531605|003e1c991cb54bf09c7a0204fa7567293b7723532785720bd12d5807cc66ab70|003e1c991cb54bf09c7a0204fa7567293b7723532785720bd12d5807cc66ab70', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a rocky height on the east coast of Lismore stands Tirefour Castle, an Iron Age broch whose dry stone wall survives up to 4.9 metres. Its finds include an enamel brooch and a Norse pin."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tirefour Castle stands on a rocky height [S2]; it is on the east coast of Lismore [S2]; it is an Iron Age broch [S1]; its wall is of dry stone [S7]; the wall survives up to 4.9 metres [S8]; finds include an enamel brooch [S4]; finds include a Norse pin [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tirefour Castle is an Iron Age broch (the kind of place the text is about) [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]; It is on the island of Lismore, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]; It stands on a rocky height on the east coast of Lismore [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]; The broch wall is built of dry stone [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]; The wall survives up to a maximum height of 4.9 metres [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]; An enamel brooch is among its finds [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]; A Norse pin is among its finds [SUPPORTED: https://en.wikipedia.org/wiki/Tirefour_Castle]"}]'::jsonb),
    ('e3243ed6-c53d-465c-83f4-e33f68b7510b'::uuid, 'card_description', 'A small axial stone circle also known as "The Druid''s Altar." Seventeen sandstone uprights originally formed a tight ring, of which 13 survive.', 'Drombeg Stone Circle is aligned south west to the setting sun. Of its seventeen sandstone stones 13 survive; at its centre an inverted pot held a young adolescent''s cremated remains.', 'teaser-card-s030:e3243ed6-c53d-465c-83f4-e33f68b7510b:card_description', 'teaser-card-s030 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '37d5e0d9c1cd63f6a165e04530095d2bfd084084fefc4d688a071401b7ec8ae3|dadeb1601f78fa99d62aab85e06dc9a1b6e4f4737904599b7a6b5c3803db6317|dadeb1601f78fa99d62aab85e06dc9a1b6e4f4737904599b7a6b5c3803db6317', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Drombeg Stone Circle is aligned south west to the setting sun. Of its seventeen sandstone stones 13 survive; at its centre an inverted pot held a young adolescent''s cremated remains."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the circle is aligned south west towards the setting sun [S6]; the circle originally had seventeen stones [S2]; the stones are sandstone [S3]; 13 of the stones survive [S2]; an inverted pot was found at the centre of the circle [S8]; the pot held the cremated remains of a young adolescent [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Drombeg Stone Circle is a stone circle (the kind of place the text is about) [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]; Its axis is aligned south west, towards the setting sun [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]; The circle originally had seventeen stones [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]; Thirteen of the seventeen stones survive [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]; The stones are sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]; An inverted pot at the centre of the circle held cremated remains [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]; The cremated remains were those of a young adolescent [SUPPORTED: https://en.wikipedia.org/wiki/Drombeg_stone_circle]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s030', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s030'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s030'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s030'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s030' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
